quests[43349] = { id = 43349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aegis von Aggramar", description = "Jetzt, wo die Aegis nicht mehr in den Händen der Legion ist, sollte sie zurück nach Dalaran gebracht werden, um dort sicher verwahrt zu werden, während die Jagd nach dem Rest der Säulen der Schöpfung weitergeht.\n\nIn der zentralen Portalkammer müsste sie sicher sein, bis die Zeit gekommen ist, wenn sie wieder gebraucht wird.", sourceObjective = "Bringt die Aegis von Aggramar zur sicheren Verwahrung in die Kammer des Wächters in Dalaran.", completion = "Die Aegis von Aggramar ist in der gut befestigten Stadt Dalaran sicher aufgehoben.\n\nIhr seid auf Euer Mission, die Legion zurückzudrängen, einen Schritt weitergekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43351] = { id = 43351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mal'Dreth the Corrupter" }
quests[43352] = { id = 43352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheitsdienst", description = "Jetzt, wo die Dämonen und Wachen so umtriebig sind, habe ich kaum noch Orte, um Schmuggelware sicher zu verstauen. Die Wachen haben eines meiner Lieblingsdepots ins Visier genommen. Ich vermute, dass sie jeden Moment meine Waren entdecken und stehlen werden.\n\nBegebt Euch zu meinem Depot und versetzt ihrer Neugier einen Dämpfer. Dafür werdet Ihr einen Greifhaken benötigen. Ihr müsst nur schauen, wo Ihr ihn an der Kante sicher befestigen könnt.\n\nEure Hilfe soll Euer Schaden nicht sein.", sourceObjective = "Beschützt Arluins Depot vor den Stadtwachen.", completion = "Ihr werdet ja zu einem richtig verlässlichen Partner!", sourceObjectiveStatus = "unverified-source-field" }
quests[43353] = { id = 43353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Celestine of the Harvest" }
quests[43354] = { id = 43354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Thisalee Crow" }
