quests[43357] = { id = 43357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Graham Silverclaw" }
quests[43358] = { id = 43358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Myonix" }
quests[43359] = { id = 43359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe eines Helden", description = "<Großmeister/Großmeisterin>, Ihr habt unseren Orden vor der sicheren Vernichtung bewahrt.\n\nEure Taten haben uns gezeigt, dass man mit Einsatz und Entschlossenheit jede Herausforderung bestehen kann. Im Angesicht Eures Vorbildes haben wir unsere Bemühungen verdoppelt und eine Technik entwickelt, mit der Eure Waffe ihr volles Potenzial entfalten kann.\n\nBitte stellt Euch vor die Schmiede des tosenden Bergs und erhebt Eure Waffe hoch in die Luft.", sourceObjective = "Tretet näher zur besagten Stelle an der Schmiede des tosenden Bergs und erhebt Eure Waffe hoch in die Luft.", progress = "Wir ehren Euch, Großmeister.", completion = "Mögen die neuen Kräfte Eurer Waffe Euch in der kommenden Zeit unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43360] = { id = 43360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Splittermaiden", description = "Ich durchstreife schon lange dieses Land und habe viele Arten der Verderbnis gesehen.\n\nDie Kreaturen in dieser Halle wurden von der Magie des gefallenen Arcan'dor verderbt. Die Dryaden sind vom Weg abgekommen und können nicht gerettet werden.\n\nIhr müsst sie vernichten und ihr Leiden beenden.", sourceObjective = "Tötet 6 Splittermaiden im Epizentrum.", completion = "Danke. Dieser Ort wird sich nie erholen, aber ihr Wahnsinn muss anderen ja keinen Schaden zufügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43361] = { id = 43361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruchstücke der Katastrophe", description = "In der nächsten Halle ruhen die Überreste des gefallenen Arcan'dor.\n\nIch werde einige Fragmente des kristallisierten Baumes an mich nehmen und sie studieren. Wir müssen herausfinden, was hinter dieser Zerstörung steckt.\n\nNur so können wir vielleicht verhindern, dass sich diese Katastrophe wiederholt.", sourceObjective = "Sammelt 5 Stücke kristallisierte Rinde.", progress = "Habt Ihr die Splitter?", completion = "Ich werde diese Stücke sorgfältig studieren. Mit etwas Glück liefern sie uns eine Antwort.", sourceObjectiveStatus = "unverified-source-field" }
quests[43362] = { id = 43362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stoff der Träume", description = "Dieser Arcan'dor gehört zu einer uralten Art. Sie wurden nicht gezüchtet, sondern erschaffen. In ihnen verband sich das Arkane mit der primitiven Macht der Druiden zu etwas, das größer war als beide zusammen.\n\nDas Arkane wird ihn bald vollständig verschlungen haben.\n\nWir können das Gleichgewicht wiederherstellen, aber dazu bedarf es wilder Magie. Magie, die in einem anderen Reich gefangen ist.\n\nIhr müsst Euch auf den Smaragdgrünen Traumpfad begeben und die Essenz des Lebens hierher zurückbringen.\n\nNur dann wird sich der Arcan'dor wieder stabilisieren und erneut erblühen.", sourceObjective = "Sammelt geläuterte Lebensessenz aus dem Smaragdgrünen Traumpfad.", progress = "Habt Ihr sie?", completion = "Ich weiß nicht, wie Ihr das geschafft habt, aber es war bestimmt nicht leicht. Viele Hürden liegen vor uns, aber Ihr scheint unaufhaltsam. Kommt, lasst uns den Arcan'dor zu neuem Leben erwecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[43363] = { id = 43363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk", sourceObjective = "Auf dem Schildchen des Geschenks steht:\n\nFrohe Feiertage, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[43364] = { id = 43364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein leicht geschütteltes Geschenk", sourceObjective = "Dieses Geschenk sieht aus, als wäre es schon ein paar Mal geschüttelt worden. Auf dem Kärtchen steht:\n\nFür {name}, ein ganz besonderer {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[43365] = { id = 43365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kreislauf geht weiter", description = "Juhu! Der Hain regeneriert sich weiter. Unsere Freunde, die Blumen, sind dankbar für Eure Hilfe.\n\nWir konnten den Hain zum großen Teil retten, aber viele lebendige Seelen sind dabei verloren gegangen.\n\nFunkelchen ist so traurig!\n\nDoch Ihr könnt helfen! Nehmt diese Tasche mit Traumsamen. Pflanzt sie in frische Leichname, dann werden mit der Zeit neue Blumen sprießen!\n\nDer Tod ist schön, und aus dem Tod entsteht die Wiedergeburt. Dieser Kreislauf muss sich fortsetzen!", sourceObjective = "Pflanzt 100 Traumsamen in Leichname.", completion = "Ich danke Euch... Das Wissen, dass das Leben weitergeht, bereitet Funkelchen Frieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[43366] = { id = 43366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talked with Mimiron" }
quests[43368] = { id = 43368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Funkelchen", sourceObjective = "Eure heldenhaften Bemühungen im Smaragdgrünen Traum waren inspirierend, {name}. Der Traum ist momentan sicher, aber solange Xavius lebt, ist er immer noch bedroht.\n\nIch werde Euch helfen. Gemeinsam können wir Azeroth vor denen schützen, die seine Zerstörung wünschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43369] = { id = 43369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Siegemaster Aedrin" }
quests[43370] = { id = 43370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Erfindung", description = "Ich experimentiere mit Technologie, die es möglich macht, die Struktur von Tieren zu ändern und so ihr Aussehen anzupassen.", sourceObjective = "Es dürfte mir möglich sein, einen Gegenstand zu erschaffen, mit dem Ihr das Aussehen von Hati ändern könnt, doch die Komponenten für einen solchen Gegenstand sind selten. Ich benötige Sturmdrüsen der Sturmjäger von Sturmheim und makellose Harpyienfedern von den Steinblutharpyien nahe Thas'talah in Val'sharah. Die Naga der Hassnattern in der Nähe der Ruinen von Nar'thalas in Azsuna besitzen angeblich die benötigten spiegelnden Schuppen. Und schließlich brauche ich eine Essenz des reinen Geistes von den meeresverbundenen Mystikern in der Blinden Marsch am Hochberg.", progress = "Dies ist meine glorreichste Erfindung... der letzten 10 Minuten.", completion = "Hier, {name}. Passt auf Hati und den Titanenblitz auf und seid bei Euren Abenteuern vorsichtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[43371] = { id = 43371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ablösung an der Front", description = "Viele unserer Ordensmitglieder waren schon viel zu lange an der Front, um jenen zu helfen, die sich der Invasion der Legion entgegenwerfen.\n\nEs wird Zeit, dass wir Verstärkungen schicken, damit sich unsere Verbündeten etwas ausruhen können.", sourceObjective = "Interagiert mit der Schlachtkarte und schließt die Mission \"Ablösung an der Front\" ab.", completion = "Hoffentlich können sich unsere {class} etwas erholen, bevor sie wieder in die Schlacht ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43372] = { id = 43372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüstern aus der Leere", description = "Unsere Priester versuchen, sich zu erholen. Es gibt allerdings verschiedene Vorstellungen davon, wie das auszusehen hat. Gilner Graumoos treibt sich im Sanktum der Leere herum und bricht immer wieder in unnachvollziehbares Gelächter aus.\n\nEr weigert sich, das Sanktum zu verlassen, stört dabei aber die anderen Priester.\n\nVielleicht könntet Ihr ihn aufsuchen und nachfragen, was mit ihm los ist?", sourceObjective = "Sprecht mit Gilner Graumoos im Sanktum der Leere.", progress = "Einige Wunden sind zu tief, um zu heilen.", completion = "Gilner hört Stimmen, oder? Jetzt bezahlt er den Preis dafür, dass er ständig seine Nase in die Schatten stecken musste.", sourceObjectiveStatus = "unverified-source-field" }
quests[43373] = { id = 43373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur die Besten der Besten", description = "Wenn wir Gilners wirre Reden verstehen wollen, muss ich eine Vision heraufbeschwören.\n\nDas ist zwar nicht die übliche Vorgehensweise, aber in unseren Reihen befinden sich die besten und weisesten Alchemisten. Sie können mir ein Extrakt zubereiten, das mir die benötigte Fähigkeit gewährt.\n\nBegebt Euch zu ihnen nach Azsuna, wo sie gerade Unterstützung an der Front leisten.", sourceObjective = "Findet Zabra Hexx in Azsuna.", completion = "Gut, dass Ihr gerade zur Stelle wart.\n\nVelen will also eine Vision heraufbeschwören? Das ist keine einfache Aufgabe, aber Yalia und ich können das ermöglichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43374] = { id = 43374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murlocgedankenkontrolle", description = "Als Yalia und ich ein paar Einheiten Gegengift an die Frontlinie nach Faronaar gebracht haben, wurden wir von einer Murlocherde angegriffen. Wir mussten die Vorräte fallen lassen und fliehen, aber Yalia hat es nicht aus dem Lager herausgeschafft. Und mir ist es auch nicht viel besser ergangen, denn meine Knochen schmerzen immer noch, nachdem sie in Stein verwandelt wurden.\n\nMöglicherweise ist Yalia noch am Leben und in Gefangenschaft. Bitte, Ihr müsst sie finden!", sourceObjective = "Rettet Yalia Weisenwisper vor den Murlocs in den Untiefen von El'dranil.", completion = "Eure schnelle Auffassungsgabe hat mich aus einer fürchterlichen Situation befreit. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[43375] = { id = 43375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein reicher Vorrat", description = "Bei dem Versuch, den Murlocs zu entkommen, haben Yalia und ich die Vorräte verloren, die wir eigentlich den Dämonenjägern in Faronaar bringen wollten.\n\nIn jeder Kiste befanden sich Fläschchen mit Salbe, die wir mit viel Zeit- und Materialaufwand hergestellt haben. Ich fürchte, unsere Verbündeten an den Frontlinien werden darunter leiden, wenn wir diese Vorräte nicht zurückbekommen.", sourceObjective = "Holt die Salbe gegen Teufelsfledermaustoxin aus den Vorratskisten, die überall in den Untiefen von El'dranil verstreut sind.", progress = "Habt Ihr unsere Vorräte?", completion = "Es lässt sich gar nicht absehen, wie viele Leben Ihr mit der Bergung dieser Phiolen gerettet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[43376] = { id = 43376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbenlieferung", description = "Eine Vision heraufzubeschwören, ist kein einfaches Unterfangen. Allein die Suche nach den Zutaten beansprucht beträchtliche Zeit. Und diese Zeit haben wir nicht. Es gibt zu viele verzweifelte Opfer an der Frontlinie, die alle unsere Salbe benötigen.\n\nAber wenn wir alle zusammenarbeiten, könnte es funktionieren.\n\nZabra und ich suchen die benötigten Zutaten für Velens Elixier zusammen, wenn Ihr die Salbe nach Faronaar bringt und die Dämonenjäger heilt. Was haltet Ihr davon?", sourceObjective = "Verwendet die Salbe bei kranken Dämonenjägern an der Faronaarfront in Azsuna.", completion = "Wir haben die Zutaten für Velens Elixier gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[43377] = { id = 43377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Das innewohnende Licht", description = "Wir dürfen die Vision des Propheten nicht ignorieren, {name}. Denn wenn wir das täten, würde alles, was uns lieb und teuer ist, an die Legion fallen.\n\nWir müssen uns auf das konzentrieren, was wir wissen: dass das Licht uns beistehen muss.\n\nIn den Hallen der Tapferkeit findet Ihr eine aufstrebende Val'kyr namens Hyrja. Holt Euch von ihr einen Funken ihres Lichts und setzt ihn in unserem Tempel frei.", sourceObjective = "Beschafft einen Funken des Lichts von Hyrja in den Hallen der Tapferkeit.", completion = "<Saa'ras beruhigende Stimme erfüllt Euren Geist.>\n\nEuer Lichtgeschenk ist sehr willkommen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[43378] = { id = 43378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Blick durch die Linse", description = "Wir haben jetzt alles, was wir benötigen, um Velens Elixier herzustellen. Aber damit auch andere seine Vision sehen können, brauchen wir noch etwas, das die Bilder in den Geist übertragen kann.\n\nMit einer Linse der Naga in der Nähe sollte es funktionieren. Ich befürchte aber, dass sie sie nicht freiwillig hergeben werden.", sourceObjective = "Beschafft die Linse der Gezeiten von Lady Hassnatter im Auge Azsharas.", progress = "Wenn Ihr durch die Linse einer mächtigen Naga blickt, könnt Ihr meine Vision sehen.", completion = "Ihr seid gerade rechtzeitig zurückgekehrt.\n\nYalia und Zabra haben soeben das Elixier fertiggestellt. Mithilfe dieser Linse könnt Ihr sehen, was ich sehe, wenn die Vision einsetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[43379] = { id = 43379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Velens Vision", description = "Jetzt habe ich alles, was ich benötige, um eine Vision heraufzubeschwören, aber eine Frage verbleibt: Seid Ihr bereit, <Zeuge/Zeugin> derselben zu werden? Selbst der kleinste Ausblick auf die Zukunft kann schwer auf der Seele lasten.\n\nSobald ich das Elixier getrunken habe, wird die Vision sehr schnell einsetzen. Wenn Ihr dann in die Linse der Gezeiten blickt, könnt Ihr sehen, was ich sehe.\n\nSagt mir Bescheid, wenn Ihr bereit seid.", sourceObjective = "Benutzt die Linse der Gezeiten, um die Vision von Prophet Velen zu sehen.", completion = "Wir werden nicht zulassen, dass dieser Dämon über unser Schicksal entscheidet. Ihr habt die Macht, unsere Zukunft zu ändern.\n\nIch habe den Pfad zur Erlösung gesehen, und Ihr werdet uns auf diesem Pfad anführen.\n\nIch muss mich jetzt zurückziehen. Die Bürde der Vision hat meinen Geist und meinen Körper ermattet.", sourceObjectiveStatus = "unverified-source-field" }
quests[43380] = { id = 43380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Sol", sourceObjective = "Geboren aus dem Licht kämpfe ich für das Licht.", sourceObjectiveStatus = "unverified-source-field" }
quests[43381] = { id = 43381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Mariella Ward", sourceObjective = "Ich schulde Euch mein Leben und noch so viel mehr.\n\nIhr habt in mir etwas gesehen, das es wert war, gerettet zu werden, und habt mich schließlich dazu gebracht, selbst daran zu glauben.\n\nGebt meinem Leben einen Sinn, {name}, und lasst mich an Eurer Seite kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43382] = { id = 43382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Natalie Seline", sourceObjective = "Ihr habt meinen Geist aus der Leere befreit, was sicherlich nicht einfach war. Ich kann nicht leugnen, dass ein Teil von mir gern für immer dortgeblieben wäre, auf ewig umgeben von Schatten.\n\nDie Leere ist erfüllt von vielen Stimmen, {name}. Stimmen, die uns allen große Sorgen bereiten sollten.\n\nWir dürfen uns nicht durch unsere unterschiedlichen Glaubensrichtungen entzweien lassen. Die {class} von Licht und Schatten müssen der Brennenden Legion gemeinsam die Stirn bieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[43383] = { id = 43383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht erwecken", description = "Dieser Funke entfaltet erst dann sein gesamtes Potenzial, wenn er vom reinen Licht der heiligsten Stätten unserer Welt erfüllt ist.\n\nSchürt diesen Funken, auf dass er wachsen und Euch eines Tages beistehen möge.", sourceObjective = "Sammelt reines heiliges Licht, indem Ihr Missionen der Ordenshalle abschließt.", progress = "<Saa'ras beruhigende Stimme erklingt in Eurem Geist.>\n\nSchürt diesen Funken mit heiligem Licht, wenn Ihr ihn zum Leben erwecken wollt.", completion = "<Mit dem sich ausbreitenden Licht beginnt der Raum, sich zu erwärmen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[43384] = { id = 43384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonische Runen", description = "Ich kann nicht tatenlos herumstehen und zulassen, dass die Legion unsere Heimat zerstört.\n\nIch lerne seit einiger Zeit ihre Sprache und entschlüssele alle Runen, derer ich habhaft werden kann, aber meine Vorräte sind sehr begrenzt.\n\nWenn ich noch mehr Runen für meine Forschung hätte, könnte ich womöglich etwas entdecken, dass uns beim Aufspüren von Balnazzar hilft.", sourceObjective = "Sammelt dämonische Runensteine von Dämonen auf den Verheerten Inseln.", progress = "Habt Ihr die Runensteine gefunden?", completion = "Diese Exemplare sind in hervorragendem Zustand! Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[43385] = { id = 43385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltration unserer Feinde", description = "Mit dem Licht an unserer Seite sollten wir unser Augenmerk darauf richten, wer unter unseren Feinden womöglich unser Verbündeter werden könnte.\n\nJeder Eurer Champions sollte in der Lage sein, sich unter unsere Feinde zu mischen, damit wir herausfinden, wie wir dabei am besten vorgehen sollten.\n\nDennoch ist es eine heikle Aufgabe. Geht umsichtig an die Sache heran.", sourceObjective = "Interagiert mit der Schlachtkarte und schließt die Mission \"Infiltration unserer Feinde\" ab.", completion = "Eure Bemühungen haben uns die notwendigen Informationen für unser weiteres Vorgehen verschafft.\n\nWir haben herausgefunden, dass sich unter den Leuten des Scharlachroten Ansturms einige Deserteure befinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[43386] = { id = 43386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesandte des Ansturms", description = "Unter den Leuten des Scharlachroten Ansturms in Nordend wurden einige Deserteure entdeckt.\n\nIch weiß, es ist schwer zu glauben, dass irgendjemand von denen unserer Sache nützlich sein könnte, aber wir müssen es versuchen.\n\nLaut der Prophezeiung wird ein alter Feind zu einem Verbündeten, also sollten wir dem nachgehen und herausfinden, ob diese Deserteure zum Licht geführt werden können.", sourceObjective = "Sucht einen neuen Verbündeten unter den alten Feinden in Neuherdweiler.", completion = "Wieso seid Ihr hier? Warum macht Ihr Euch die Mühe, mich zu retten? Ich war darauf vorbereitet, zu sterben. Ich sollte für die furchtbaren Dinge, die ich getan habe, bezahlen...", sourceObjectiveStatus = "unverified-source-field" }
quests[43387] = { id = 43387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharlachrote Erlösung", description = "Das Licht scheint auf mich herab, {name}! Zum ersten Mal im Leben spüre ich es!\n\nIch hatte keine Hoffnung mehr und war bereit, für die Dinge zu sterben, die ich im Namen des Scharlachroten Kreuzzugs tat, aber dann seid Ihr erschienen! Ihr seid meine Hoffnung auf Erlösung.\n\nBitte lasst mich beweisen, dass ich eine zweite Chance verdiene. Lasst mich diejenigen töten, denen ich einst treu ergeben war!", sourceObjective = "Helft Mariella der Ketzerin, Wiedergutmachung für ihre Fehler zu leisten, indem Ihr Mitglieder des Scharlachroten Ansturms in Neuherdweiler tötet.", completion = "Das Licht scheint wahrhaftig auf mich, {name}. Eure Anwesenheit hat das bewiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43388] = { id = 43388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung der Abtrünnigen", description = "Ihr müsst wissen, dass es noch andere wie mich gibt. Andere, die den Schleier abgenommen haben, mit dem der Scharlachrote Kreuzzug so lange unsere Augen bedeckte.\n\nSie wurden in Käfige gesteckt und wie Tiere behandelt, nur weil ihr Glaube nicht länger mit dem übereinstimmt, was der Ansturm für gut und heilig hält.\n\nSie möchten sich rehabilitieren. Wir sollten versuchen, sie zu befreien, wenn Ihr meint, dass ihre Leben wert sind, gerettet zu werden.", sourceObjective = "Rettet Abtrünnige des Ansturms in Neuherdweiler.", completion = "Die Gnade, die Ihr uns erwiesen habt, treibt mir die Tränen in die Augen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43389] = { id = 43389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerwartete Gäste", description = "Ihr habt mich vor dem Galgen gerettet und mir so geholfen, meinem Schicksal zu entgehen. Doch die Erlaubnis, an Eurer Seite gegen den Scharlachroten Ansturm zu kämpfen, hat mein Herz und meinen Geist wirklich von meiner lange empfundenen Schuld befreit.\n\nIch möchte Teil von etwas sein, das größer ist als ich, von einer edlen Sache, die die Bedeutung des Lichts nicht verzerrt.\n\nLasst mich zu Eurem Tempel reisen und Vergebung vom Propheten erflehen. Ich mag kein willkommener Gast sein, aber ich muss diese Reise machen, um meine Erlösung zu vervollständigen.", sourceObjective = "Kehrt zu Alonsus Faol im Netherlichttempel zurück.", completion = "Ist das der Feind, den wir als Verbündeten willkommen heißen sollen?", sourceObjectiveStatus = "unverified-source-field" }
quests[43390] = { id = 43390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergessene Schatten", description = "Das Licht wandelt unter uns, genau wie einer unserer Feinde. Ihr habt gut daran getan, die Prophezeiung zum Leben zu erwecken, aber sie ist noch nicht vollständig.\n\nDie Schatten müssen sich erheben, und zu diesem Zweck muss der Kult der Vergessenen Schatten wiederhergestellt werden.\n\nIhr findet die verbliebenen Anhänger auf dem Friedhof im Dämmerwald. Sie halten sich in der Nähe des Grabs ihres Anführers auf.", sourceObjective = "Begebt Euch in den Dämmerwald und trefft Euch mit einem Mitglied des Kults der Vergessenen Schatten.", completion = "Alonsus hat Euch also geschickt? Er hat bisher nicht allzu viel Interesse an uns gezeigt.\n\nNatürlich sind wir auch nicht grade bekannt dafür, dem Licht zu folgen, wenigstens nicht so, wie die Meisten das gerne hätten.\n\nWir empfangen auch die Schatten mit offenen Armen und finden unseren Glauben im Gleichgewicht zwischen den beiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[43391] = { id = 43391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Leere", description = "Unsere Anführerin wurde wegen ihrer Überzeugungen ermordet. Zumindest ist das die vorherrschende Meinung.\n\nNatalie Seline wusste, welches Schicksal sie erwartete, und hatte sich gegen den unvermeidlichen Tod gewappnet.\n\nIn der Nacht, als sie angegriffen wurde, entsandte sie ihren Geist in die Leere. Den genauen Ort kennt nur Natalie selbst.\n\nIn einem ihrer vielen Tagebücher hatte sie einen Zauber niedergeschrieben, mit dem man ihren Geist zurückholen kann. Leider ist dieses Buch in die Hände ihrer Mörder geraten.\n\nOhne das Tagebuch bleibt ihr Geist für uns unerreichbar.", sourceObjective = "Holt Natalies Tagebuch von Zwielichtfürst Urgrok zurück.", progress = "Wir wachen über Natalies Leichnam in der Hoffnung, dass ihr Geist eines Tages zurückkehrt.", completion = "Das ist es! Das ist das Tagebuch mit dem Zauber, der zu Natalies Geist führt!", sourceObjectiveStatus = "unverified-source-field" }
quests[43392] = { id = 43392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Leere wartet", description = "Das ist Natalies Handschrift, kein Zweifel. Der Eintrag wurde wohl in großer Eile geschrieben, aber die Aussage ist eindeutig: Der Zauber in diesem Tagebuch wird uns zu Natalies Geist führen, aber er muss an einem Schattenaltar in den Katakomben gesprochen werden.\n\nOdessa und ich müssen Natalies Leichnam bewachen, aber mit Euren Fähigkeiten sollte der Zauber für Euch ein Kinderspiel sein.", sourceObjective = "Lest Natalies Tagebuch am Schattenaltar in den Katakomben, um die Leere zu betreten und ihren Geist zurückzuholen.", completion = "Der Lockruf der Leere ist verführerisch. Es gab Zeiten, da fühlte ich mich auf ewig verloren.\n\nDanke, dass Ihr mich befreit habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[43393] = { id = 43393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anwachsende Schatten", description = "Die Kunde über meine Rückkehr wird sich wie ein Lauffeuer unter allen verbreiten, die meinen Glauben teilen. Schon bald werden sich die Schatten in ganz Azeroth erheben, aber das dürfte Euch wohl kaum überraschen.\n\nWie auch immer Euer Plan aussieht, ich hoffe, der Kult der Vergessenen Schatten zählt darin immer noch zu den Verbündeten.", sourceObjective = "Kehrt zu Alonsus Faol am Netherlichttempel zurück.", completion = "Die Verlassenen werden durch Natalie Selines Rückkehr neuen Mut schöpfen, genau wie wir. Sie ist ein Zeichen, dass sich die Prophezeiung erfüllt.", sourceObjectiveStatus = "unverified-source-field" }
quests[43394] = { id = 43394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über die Legionslinien hinaus", description = "Ich habe eine Nachricht vom Hochlord erhalten, dass einige Paladine und Priester nach einer Schlacht am Teufelsfeuervorstoß in Gefangenschaft geraten sind. Eure Priesterin Delas Mondfang gehört auch zu diesen Gefangenen.\n\nMan hat sie durch das Dämonenportal auf die Legionswelt Niskara verschleppt.\n\nWenn wir die Gefangenen befreien wollen, brauchen wir die Hilfe der Konklave.", sourceObjective = "Benutzt das Dämonenportal am Teufelsfeuervorstoß, um nach Niskara zu gelangen und nach Aponi Lichtmähne zu suchen.", completion = "Dem Licht sei Dank. Ich wollte die Hoffnung nicht aufgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[43395] = { id = 43395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündete des Lichts", description = "Sowohl Arator als auch Delas befinden sich noch irgendwo auf diesem elenden Fels... zusammen mit vielen anderen unserer Verbündeten.\n\nWir können sie nicht so einfach zurücklassen, {name}.", sourceObjective = "Rettet Ritter der Silbernen Hand oder Priester der Konklave und rettet Arator den Erlöser und Delas Mondfang.", completion = "Ich habe von Delas Mondfang schon viel über Euer Heldentum gehört. Dank Euch wurden viele Leben gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[43396] = { id = 43396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gedanken des Feindes", description = "Die Kerkermeister der Dämonen haben über eine bevorstehende Invasion gesprochen. Ihre Armee sammelt sich für ein wirklich großes Vorhaben, und das bereitet mir große Sorgen.\n\nWir müssen so viel wie möglich über ihre Pläne herausfinden.", sourceObjective = "Sucht nach Informationen der Legion, der Sternenkarte und dem Abbild von Velen und vernichtet dann die Brutkönigin Aramis.", completion = "Die Informationen, die Ihr gesammelt habt, sind ein weiterer Beweis, dass wir die Prophezeiung nicht ignorieren können. Der Angriff der Legion steht kurz bevor, und ohne die Paladine als unsere Verbündeten im Lichte werden wir ihn nicht überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[43397] = { id = 43397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsam sind wir stark", description = "Ihr und Delas seid ja keine Unbekannten für die Paladine, also gewährt Euch ihr Kriegsrat vielleicht eine Audienz.\n\nBegebt Euch zum Sanktum des Lichts und bittet die Paladine, uns bei der Verteidigung des Netherlichttempels gegen Balnazzar zu helfen.", sourceObjective = "Begebt Euch zum Sanktum des Lichts, um mit Lady Liadrin zu sprechen und den Kriegsrat anzuhören.", completion = "Wir werden bei der Verteidigung des Netherlichttempels helfen und Balnazzar eine Falle stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43398] = { id = 43398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Alonsus Faol", sourceObjective = "Ich wusste im Moment unserer Begegnung auf den stillen Feldern von Tirisfal, dass Ihr die {class} vereinen würdet.\n\nAuch wenn es mir zur Ehre gereichen würde, unseren Anführer gefunden zu haben, so glaube ich doch, dass Ihr in Wahrheit uns gefunden habt.\n\nUnsere gemeinsame Zeit hat gerade erst begonnen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[43399] = { id = 43399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befestigung des Tempels", description = "Wir haben alle so hart gearbeitet, diesen Tempel zu einem Ort zu machen, auf den alle Priester stolz sein können. Es wäre eine Schande, wenn die Brennende Legion ihn zerstören würde.\n\nWir müssen unsere Verteidigung stärken und uns auf den Angriff vorbereiten. Mit den richtigen Ressourcen können wir den Tempel in eine so gut wie uneinnehmbare Festung verwandeln.", sourceObjective = "Schließt 10 Weltquests ab.", completion = "Das sollte genügen, um unsere Verteidigung zu verstärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[43400] = { id = 43400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchtstein", description = "Um uns auf die Schlacht vorzubereiten, brauchen wir die besten Rüstungen und Waffen, die wir finden können.\n\nLeuchtstein ist ein verzaubertes Material, das selbst großen Mengen von Teufelsmagie standhält.\n\nMan findet kleinste Vorkommen überall auf den Verheerten Inseln. Viele der einheimischen Völker verwenden es in der Metallverarbeitung.\n\nWir sollten unsere Champions ausschicken, um Feinde auf den Verheerten Inseln zu überfallen. Unter ihren Vorräten sollte sich jede Menge Leuchtstein finden lassen.", sourceObjective = "Sammelt 50 Stücke Leuchtstein, indem Ihr Champions auf Missionen der Reihe \"Leuchtstein\" schickt.", progress = "Habt Ihr schon Leuchtstein gefunden?", completion = "Das ist genug Leuchtstein, um Rüstungen und Waffen für eine ganze Armee herzustellen. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[43401] = { id = 43401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht in der Dunkelheit", description = "Die Brennende Legion greift an!\n\nIch werde hierbleiben und die Verteidigung des Tempels vorbereiten. Ihr müsst sofort unsere Verbündeten in Dalaran aufsuchen und ihnen mitteilen, dass der Kampf begonnen hat!\n\nBeeilt Euch, {name}. Ich weiß nicht, wie lange wir Balnazzar aufhalten können.", sourceObjective = "Verteidigt gemeinsam mit den Paladinen den Netherlichttempel und vernichtet Lord Balnazzar.", completion = "Ihr habt gut gekämpft, Hohepriester.", sourceObjectiveStatus = "unverified-source-field" }
quests[43402] = { id = 43402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hohepriester des Netherlichts", description = "Ihr habt die Prophezeiung erfüllt, aber noch wichtiger ist, dass Ihr die Priester von Azeroth geeint habt.\n\nWir sollten einen Moment innehalten und Eurem Erfolg den gebührenden Respekt erweisen.", sourceObjective = "Hört zu, während die Konklave der Priester Euch würdigt.", progress = "Auf Euren Triumph! Hurra!", completion = "Wir neigen unser Haupt in Ehrfurcht vor Euch, Hohepriester.", sourceObjectiveStatus = "unverified-source-field" }
quests[43403] = { id = 43403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Inseln", description = "Als Druiden ist es unsere Aufgabe, die Natur und damit unsere Heimat Azeroth zu verteidigen.\n\nAuf den Verheerten Inseln wird überall gekämpft. Die Brennende Legion marschiert voran und zahlreiche Verbündete rufen uns zu Hilfe.\n\nWir müssen uns erst auf die Verteidigung konzentrieren, bevor wir einen Angriff auf den Alptraum erwägen können.\n\nHelft unseren Verbündeten auf den Verheerten Inseln und kehrt zu mir zurück, sobald die Situation unter Kontrolle ist.", sourceObjective = "Schließt 10 Weltquests ab.", completion = "Ihr habt den Hain der Träume ehrwürdig vertreten, Erzdruide. Ihr habt vielen geholfen und Eure Siege werden noch viele Jahre lang in aller Munde sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[43404] = { id = 43404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Versammlung für den Großmeister", description = "{name}, ähh... {class}t,\n\nIhr werdet gebeten, Euch wegen einer äußerst wichtigen Angelegenheit zum Tempel der Fünf Sonnenaufgänge zu begeben.\n\nMeister Ponshu und der Rest des Verheerten Tempels warten auf Euch!", sourceObjective = "Meldet Euch bei Eisenkörper Ponshu im Tempel der Fünf Sonnenaufgänge.", sourceObjectiveStatus = "unverified-source-field" }
quests[43405] = { id = 43405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da-Nel's Second Quest" }
quests[43406] = { id = 43406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf nach dem Todesgebieter" }
quests[43407] = { id = 43407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe eines Helden", description = "Ich freue mich, berichten zu können, dass die Verbesserungen an der Seelenschmiede abgeschlossen sind!\n\nWenn Ihr bereit seid, werden wir sie benutzen, um die wahren Kräfte Eurer Waffe freizusetzen!", sourceObjective = "Tretet näher zur besagten Stelle vor der Seelenschmiede und erhebt Eure Waffe hoch in die Luft.", progress = "Geleidet Euch wohl, Todesgebieter.", completion = "Mögen die neuen Kräfte Eurer Waffe Euch gut dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43408] = { id = 43408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einberufung des Erzdruiden" }
quests[43409] = { id = 43409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe eines Helden", description = "{class}t, in der kurzen Zeit, die wir miteinander verbracht haben, habt Ihr dem Zirkel sehr geholfen.\n\nEure Entschlossenheit hat uns inspiriert und wir haben eine neue Technik entdeckt, mit der die Macht Eurer Waffe an den Smaragdgrünen Traum gebunden wird!\n\nAlles ist vorbereitet. Wenn Ihr bereit seid, können wir anfangen.", sourceObjective = "Tretet näher zur besagten Stelle vor der Saat der Zeitalter und erhebt Eure Waffe hoch in die Luft.", progress = "Wir ehren Euch, Erzdruide.", completion = "Mit dieser neuen Macht wird die Legion fallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[43410] = { id = 43410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meister wird verlangt" }
quests[43411] = { id = 43411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meister wird verlangt" }
quests[43412] = { id = 43412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe eines Helden", description = "Ich freue mich, berichten zu können, dass die Verbesserungen an der Schmiede abgeschlossen sind!\n\nWenn Ihr bereit seid, werden wir sie benutzen, um die wahren Kräfte Eurer Waffe freizusetzen!", sourceObjective = "Tretet näher zur besagten Stelle an der Verfluchten Schmiede der Nathrezim und erhebt Eure Waffe hoch in die Luft.", completion = "Mögen die neuen Kräfte Eurer Waffen Euch gut dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43413] = { id = 43413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Wirbel im Nether" }
quests[43414] = { id = 43414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe eines Helden", description = "{class}t, unsere Forschung den Teufelsblutaltar betreffend hat sich als nützlich erwiesen. Wir haben ein Ritual entwickelt, mit dem sich die volle Macht Eurer Artefaktwaffe entfesseln lässt!\n\nIhr müsst es nur sagen und wir werden sofort mit dem Ritual beginnen!", sourceObjective = "Tretet näher zur besagten Stelle vor dem Teufelsblutaltar und erhebt Eure Waffe hoch in die Luft.", completion = "Mit dieser neuen Macht wird uns nichts mehr aufhalten können!", sourceObjectiveStatus = "unverified-source-field" }
quests[43415] = { id = 43415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe eines Helden", description = "{class}t, in der kurzen Zeit, die wir miteinander verbracht haben, habt Ihr viel für unseren Orden getan.\n\nEure Worte und Taten haben uns inspiriert, unsere Anstrengungen zu verdoppeln, und ich bin stolz, zu verkünden, dass wir eine neue Technik entdeckt haben, die Euch von Nutzen sein könnte.\n\nWenn Ihr einen Moment Zeit habt, {class}t, würde ich Euch gerne die Früchte unserer Arbeit zeigen.", sourceObjective = "Tretet näher zur besagten Stelle an der Schmiede des Wächters und erhebt Eure Waffe hoch in die Luft.", completion = "Möge diese Kraft Euch in der kommenden Zeit unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43416] = { id = 43416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure" }
quests[43417] = { id = 43417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister rufen" }
quests[43418] = { id = 43418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe eines Helden", description = "<Scharfseher/Scharfseherin>, seit Ihr Euch uns angeschlossen habt, habt Ihr viel getan, um den Irdenen Ring zu unterstützen.\n\nEure Bemühungen sind nicht unbemerkt geblieben. Die Geister haben all Eure Taten beobachtet und sind zufrieden. Sie haben mir außerdem eine Technik gezeigt, mit der die wahre Macht Eurer Waffe entfesselt werden kann!\n\nDas Ritual ist vorbereitet. Wenn Ihr so weit seid, können wir beginnen.", sourceObjective = "Tretet näher zur besagten Stelle vor dem uralten Elementaraltar und erhebt Eure Waffe hoch in die Luft.", completion = "Möge diese Kraft Euch in der kommenden Zeit unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43419] = { id = 43419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht ruft" }
quests[43420] = { id = 43420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe eines Helden", description = "{class}t, in unserer kurzen Zeit zusammen habt Ihr viel getan, um der Konklave zu helfen. Jetzt, wo die Arbeit am Altar des Lichts und Schattens beendet ist, ist es an der Zeit, dass wir Euch helfen. Wir haben eine Methode entdeckt, um die volle Kraft Eurer Waffe zu entfalten!\n\nBitte stellt Euch vor den Altar und erhebt Eure Waffe hoch in die Luft.", sourceObjective = "Tretet näher zur besagten Stelle vor dem Altar des Lichts und Schattens und erhebt Eure Waffe hoch in die Luft.", completion = "Mögen die neuen Kräfte Eurer Waffe Euch gut dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43421] = { id = 43421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rabe ruft" }
quests[43422] = { id = 43422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe eines Helden", description = "Ich freue mich, Euch mitteilen zu können, dass die Verbesserungen am Tiegel abgeschlossen sind!\n\nWenn Ihr vorbereitet seid, werden wir ihn benutzen, um die wahren Kräfte Eurer Waffen freizusetzen!", sourceObjective = "Tretet näher zur besagten Stelle am Tiegel der Ungekrönten und erhebt Eure Waffe hoch in die Luft.", completion = "Mögen Eure neuen Waffen Euch gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[43423] = { id = 43423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe eines Helden", description = "Ich freue mich, Euch mitteilen zu können, dass die Verbesserungen am Altar der Ewigen Jagd abgeschlossen sind!\n\nWenn Ihr bereit seid, werden wir ihn benutzen, um das volle Potenzial Eurer Waffe freizusetzen!", sourceObjective = "Tretet näher zur besagten Stelle vor dem Altar der Ewigen Jagd und erhebt Eure Waffe hoch in die Luft.", completion = "Mögen die neuen Kräfte Eurer Waffe Euch gut dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43424] = { id = 43424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe eines Helden", description = "{class}t, Ihr habt die Silberne Hand zusammenrücken lassen, wie es noch nie ein {class}t vermocht hat. Ihr habt uns gezeigt, dass Entschlossenheit und Vertrauen in das heilige Licht jede Herausforderung überwinden kann.\n\nEurem Beispiel folgend haben unsere Arbeiter sich abgerackert, um den Altar der Uralten Könige zu verbessern, damit er das wahre Potential Eurer Waffe freisetzen kann.\n\nIhre Arbeit ist jetzt abgeschlossen! Tretet vor, wenn Ihr bereit seid, und wir werden beginnen.", sourceObjective = "Tretet näher zur besagten Stelle vor dem Altar der Uralten Könige und erhebt Eure Waffe hoch in die Luft.", completion = "Möge diese gesegnete Kraft Euch in der kommenden Zeit unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43425] = { id = 43425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe eines Helden", description = "Ich habe Euch beobachtet, {name}.\n\nWieder und wieder habt Ihr die Valarjar mit erhobener Waffe in den Krieg geführt, wieder und wieder toste der Applaus für Eure Siege durch die Hallen der Tapferkeit!\n\nJetzt, wo die Verbesserungen an der Schmiede beendet sind, ist es an der Zeit, das volle Potenzial Eurer Waffe zu entfesseln. Trefft mich jetzt an der Schmiede.", sourceObjective = "Trefft Euch mit Odyn an seiner Schmiede und erhebt Eure Waffe an der gekennzeichneten Stelle.", progress = "Ich ehre Euch, Schlachtenfürst.", completion = "Möge Eure neue Waffe Euch gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
