quests[43441] = { id = 43441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zweite Waffe", description = "Wir haben solide Hinweise über andere uralte Waffen, die Ihr suchen könntet, sofern es Euch nicht reicht, nur ein berühmtes und mächtiges Stück Geschichte in den Händen zu halten.\n\nIch werde Euch einen Überblick der Möglichkeiten bereitlegen. Lasst es mich wissen, wenn Euch etwas davon interessiert.", sourceObjective = "Wählt ein zweites Artefakt, das Ihr suchen wollt.", completion = "Dann steht die Entscheidung fest.", sourceObjectiveStatus = "unverified-source-field" }
