quests[43460] = { id = 43460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Kiranys Abendwisper" }
quests[43461] = { id = 43461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit des Reflektierens", description = "Es ist an der Zeit, dass wir uns die Ereignisse, die zu diesem Moment geführt haben, in Erinnerung rufen: eine Würdigung unserer großen Geschichte und der Begebenheiten, die sie prägten.", sourceObjective = "Gebt die richtige Antwort auf eine von Ju'Pas Fragen zur Geschichte von Azeroth.", progress = "So lasst uns über die Ereignisse sprechen, die bereits geschehen sind.", completion = "Ein Moment der Rückbesinnung auf unsere Erfolge. Ein Tag, an dem wir in die Zukunft und auf unsere Bestimmung blicken. Ein Jahr der Rückschau darauf, was es bedeutet, zu wachsen, und eine Lebensspanne an Erinnerungen für jene, die tapfer ihren Weg gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43462] = { id = 43462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutter Ozram", description = "Die teuflischen Wichtel hier in der Gegend sind wirklich eine Plage für unserer Verbündeten, die dort unten die Lager verteidigen.\n\nEs handelt sich um die Brut einer boshaften Wichtelmutter namens Mutter Ozram, die sich öfter auf einem Hügel im Süden herumtreibt.\n\nVernichtet sie, wir kümmern uns dann um ihre Brut.", sourceObjective = "Tötet Mutter Ozram.", completion = "Ein Glück, dass wir die los sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[43463] = { id = 43463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes of a Fallen Crusader Tracking Quest" }
quests[43464] = { id = 43464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes of a Fallen Crusader Tracking Quest 2" }
quests[43465] = { id = 43465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes of a Fallen Crusader Tracking Quest" }
quests[43467] = { id = 43467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boarding the Fel Hammer" }
quests[43468] = { id = 43468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut für den Wolf", description = "Wir haben eine Anfrage von Winstone Wolf. Er sagt, er bräuchte eine größere Menge Dämonenblut. Den Zweck hat er nicht angegeben, und ich habe ihn nicht danach gefragt.\n\nIch wäre geneigt, diesen Auftrag zeitnah zu erfüllen. Der Wolf bittet selten um etwas. Wenn er doch mal pfeift, sollten wir springen. Er liefert schließlich mehr als zuverlässige Ergebnisse.\n\nWir sollten ihm die gleiche professionelle Zuvorkommenheit erweisen.", sourceObjective = "Sammelt 50 Einheiten Teufelsblut.", progress = "Die Zeit läuft, {name}. Habt Ihr das Blut?", completion = "Das sollte reichen. Ich sorge dafür, dass der Wolf jeden Tropfen davon bekommt.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[43469] = { id = 43469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Mathias?", description = "Meister Mathias Shaw ist der Anführer des Nachrichtendienstes der Allianz, auch bekannt als SI:7. Außerdem ist er jetzt wohl ein Schreckenslord.\n\nBesser gesagt, ein listiger Schreckenslord hat seinen Platz eingenommen, während er gefangen gehalten wird.\n\nEs ist von höchster Wichtigkeit, dass wir den Hochstapler vor dem neuen König von Sturmwind bloßstellen. Sollte uns das nicht gelingen, wird er die Allianz von innen heraus zerfressen und der Brennenden Legion auf dem Silbertablett präsentieren.", sourceObjective = "Benutzt die Späherkarte und schließt die Missionen der Reihe \"Jagd um die Welt - schnappt Mathias Shaw\" ab.", completion = "Jetzt wissen wir, dass unser Freund vom SI:7 in der Teufelsseelenbastion in Suramar festgehalten wird. Ich weiß nicht, warum wir dort nicht zuerst nachgesehen haben.\n\nIch gehe davon aus, dass Ihr schon einen ungefähren Plan dafür habt, wie wir ihn herausholen? Ich habe jedenfalls einen. Vielleicht können wir sie ja kombinieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[43470] = { id = 43470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unkraut ausmerzen", description = "Die Ungekrönten sind wie Gärtner. Wir schneiden hier und da mal etwas weg. Nur einen einzelnen Ast zu beschneiden, mag sinnlos erscheinen, bis man ein Stück zurückgeht und einen Blick auf den Garten im Gesamtbild wirft.\n\nWas die Verheerten Inseln als Gesamtbild betrifft, müssen wir entschlossen vorgehen. Die Streitkräfte, die sich gegen Azeroth versammelt haben, marschieren schnell. Wir müssen einige sehr hässliche Blumen abschneiden, damit unser Garten wieder schön ist. Seht Ihr das nicht auch so, {name}?", sourceObjective = "Schließt 10 Weltquests ab.", completion = "So, das ist doch viel besser. Jetzt ist unser Garten meiner Meinung nach viel schöner.", sourceObjectiveStatus = "unverified-source-field" }
quests[43471] = { id = 43471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Historiker", description = "{name}, jedes Jahr reise ich nach Sturmwind, um Abenteurern wie Euch zu helfen, unsere gemeinsame Geschichte zu würdigen. Wir müssen zwar die Zukunft immer fest im Blick behalten, aber wir dürfen dennoch nicht unsere Vergangenheit vernachlässigen. Besucht mich in der Königlichen Bibliothek von Sturmwind. Dort können wir uns weiter unterhalten.", sourceObjective = "Trefft Euch mit Historiker Llore in der Königlichen Bibliothek von Sturmwind.", completion = "{name}, da seid Ihr ja. Ihr habt also meinen Brief erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[43472] = { id = 43472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Historiker", description = "{name}, jedes Jahr reise ich nach Orgrimmar, um Abenteurern wie Euch zu helfen, unsere gemeinsame Geschichte zu würdigen. Wir müssen zwar die Zukunft immer fest im Blick behalten, aber wir dürfen dennoch nicht unsere Vergangenheit vernachlässigen. Besucht mich im Tal der Geister. Dort können wir uns weiter unterhalten.", sourceObjective = "Trefft Euch mit Historiker Ju'pa im Tal der Geister.", completion = "{name}, da seid Ihr ja. Ihr habt also meinen Brief erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[43473] = { id = 43473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Experimentaltrank: Testsubjekte gesucht", sourceObjective = "Möchtet Ihr Euch ein paar schnelle Münzen verdienen? Ich brauche neue Testsubjekte für einen meiner Tränke.\n\nDieser Trank verdankt sein ganz besonderes Aroma den Froschaugen, den Froschherzen und... Moment mal. Ich muss noch mal auf die Zutatenliste schauen.\n\nHm... Tja... Also dann...\n\nIm Grunde ist das frisch gepresster Froschsaft. Hoch die Tassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[43474] = { id = 43474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Experimentaltrank: Testsubjekte gesucht", sourceObjective = "Möchtet Ihr Euch ein paar schnelle Münzen verdienen? Ich brauche Testsubjekte für meinen neuesten Trank.\n\nLeider kann ich ihn nicht an mir selbst testen, weil ich gegen ein paar der Zutaten allergisch bin. Auf mich hätte er eine hoch toxische Wirkung. Aus meiner Sicht ist das hier eine große Flasche voller Gift.\n\nAlso, Kopf in Nacken!", sourceObjectiveStatus = "unverified-source-field" }
quests[43475] = { id = 43475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Experimentaltrank: Testsubjekte gesucht", sourceObjective = "Möchtet Ihr Euch ein paar schnelle Münzen verdienen? Ich brauche Testsubjekte für diesen Trank.\n\nIch habe den Großteil meiner Zeit und Energie auf seine Wirksamkeit verwendet und nicht auf seine... kulinarischen Qualitäten. Ignoriert also einfach, wie er schmeckt, riecht, aussieht und sich im Mund anfühlt.\n\nUnd ich glaube, aus diesem besonderen Trank kommen auch GERÄUSCHE... Die solltet Ihr auch ignorieren.\n\nProst!", sourceObjectiveStatus = "unverified-source-field" }
quests[43476] = { id = 43476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Experimentaltrank: Testsubjekte gesucht", sourceObjective = "Möchtet Ihr Euch ein paar schnelle Münzen verdienen? Ich brauche neue Testsubjekte für eines meiner Lieblingstrankrezepte.\n\nIch muss gestehen, dass die letzten Tests mit dieser Art Trank meinen Testsubjekten nicht sonderlich gut bekommen sind. Das ist auch der Grund, warum ich die Leute jetzt für diese Tests bezahlen muss.\n\nLasst ihn Euch schmecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[43477] = { id = 43477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Experimentaltrank: Testsubjekte gesucht", sourceObjective = "Möchtet Ihr Euch ein paar schnelle Münzen verdienen? Ich brauche Testsubjekte für meinen neuesten Trank.\n\nIch habe zahlreiche Anfragen für vegetarische Tränke erhalten. Man glaubt ja gar nicht, wie oft in diesen Tränken Fleisch enthalten ist!\n\nUnd um auf die fleischlichen Anteile verzichten zu können, musste ich ein paar Veränderungen vornehmen. Ich hoffe, zermahlene Glasscherben und faulige Fischeingeweide machen Euch nichts aus?\n\nFische sind doch keine Tiere, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[43478] = { id = 43478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Experimentaltrank: Testsubjekte gesucht", sourceObjective = "Möchtet Ihr Euch ein paar schnelle Münzen verdienen? Ich brauche Testsubjekte, die unter meiner Beobachtung einen Trank trinken.\n\nIch habe bei diesem Trank große Schwierigkeiten gehabt, die gewünschten Effekte zu erzielen. Meistens scheinen die Leute nur darüber zornig zu werden, dass ich sie so etwas trinken lasse.\n\nAlso los, runter damit.", sourceObjectiveStatus = "unverified-source-field" }
quests[43479] = { id = 43479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Welt ist nicht genug", description = "Jetzt, nachdem wir den Garten zurückgeschnitten haben, müssen wir den verfaulenden Baumstumpf in der Mitte ausgraben.\n\nMit anderen Worten, wir müssen verhindern, dass die Streitkräfte des Chaos die Verheerten Inseln überrennen. Sicher bekommen wir dafür Hilfe.\n\nIch habe jedoch keinen Zweifel daran, dass das von Euch gewählte Ziel das klügste aus Sicht der Ungekrönten sein wird.", sourceObjective = "Schließt 1 beliebige seltene Elite-Weltquest ab. Diese Quests sind durch blaue Ausrufezeichen, umrahmt von einem goldenen Drachen, auf den Gebietskarten gekennzeichnet.", completion = "Ihr habt Eure Ziele wahrlich gut gewählt. Die Ungekrönten können sich glücklich schätzen, Euch in ihren Reihen zu haben, werter Herr.", sourceObjectiveStatus = "unverified-source-field" }
quests[43480] = { id = 43480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huk'roth the Houndmaster" }
quests[43481] = { id = 43481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Arcanist Lylandre" }
quests[43483] = { id = 43483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsvernichtung" }
quests[43484] = { id = 43484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Rauren" }
quests[43485] = { id = 43485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine brennende Ablenkung", description = "Wir brauchen ein Ablenkungsmanöver, wenn wir Mathias Shaw aus seinem Gefängnis in der Teufelsseelenbastion befreien wollen.\n\nUnd zwar ein großes.\n\nEin paar strategisch verteilte Sprengladungen sollten genügen. Noggenfogger spielt mit und hat einige Bomben für unsere Sache gestiftet. Nach seinen früheren Erpressungsversuchen will er jetzt wohl gut Wetter machen.\n\nIch kann jemanden vorausschicken, der die besten Orte markiert. Möchtet Ihr die Ehre übernehmen, die Bomben zu platzieren?", sourceObjective = "Platziert Noggenfoggers Kawummsbomben auf Eurem Weg durch die Teufelsseelenbastion und betätigt dann den Zünder, um sie hochzujagen.", completion = "Das war ja mal ein Ablenkungsmanöver!", sourceObjectiveStatus = "unverified-source-field" }
quests[43486] = { id = 43486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kodex knacken", description = "Ich habe den Kodex der Befehlsgewalt untersucht, den Ihr aus Faronaar geborgen habt.\n\nEr ist Balnazzar wichtig, aber WARUM? Was steht darin? Wenn wir diesen Code knacken, könnte der Kodex uns sicher wertvolle Informationen liefern.\n\nIch kenne jemanden, der uns vielleicht helfen kann: eine Priesterin namens Delas Mondfang. Sie hat Eredun, die Sprache der Dämonen, studiert.\n\nBringt ihr den Kodex nach Dalaran und sagt ihr, dass ich Euch geschickt habe.", sourceObjective = "Sprecht mit Delas Mondfang in Dalaran.", completion = "Aponi hat Euch geschickt? Wie geht es ihr? In diesen Zeiten ist es wirklich schwer, Verbindung mit den eigenen Freunden zu halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[43487] = { id = 43487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf die Violette Festung: Das Teufelslexikon", description = "Ich studiere zwar die Sprache der Dämonen, bekomme aber nur selten Schriftstücke in die Finger.\n\nEs gibt ein Gerücht über ein Buch namens Teufelslexikon, das von einem uralten Gelehrten verfasst wurde, der sowohl Eredun als auch Draenei sprach. Wenn ich doch nur dieses Buch hätte. Was ich nicht alles daraus lernen könnte!\n\nIch habe gehört, das Buch befindet sich im Besitz eines mächtigen Gefangenen in der Violetten Festung.\n\nBringt mir das Buch, dann komme ich mit meiner Arbeit hier viel schneller voran.", sourceObjective = "Besorgt Euch ein Teufelslexikon von einem mächtigen Gefangenen in der Violetten Festung.", progress = "Ich spreche zwölf Sprachen fließend und hoffe, noch einige weitere zu erlernen.", completion = "Ja, ich glaube, das ist es! Schaut Euch das gute Stück nur an, {name}. Dieses Wissen wird mir gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[43488] = { id = 43488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut unseres Feindes", description = "Ich habe schon zuvor dämonische Artefakte gesehen, {name}.\n\nDie Siegel der Legion werden nur in Anwesenheit dämonischen Blutes sichtbar.\n\nIch spüre, dass die Zeit drängt. Bringt mir so schnell wie möglich eine große Menge Dämonenblut, damit ich das Buch für Euch übersetzen kann.", sourceObjective = "Schickt Eure Champions auf Missionen der Reihe \"Das Blut unseres Feindes\" gegen die Brennende Legion aus und sammelt 5 Fläschchen Dämonenblut.", progress = "Beim letzten Mal habe ich es mit einem lebenden Dämon versucht. Das ging ziemlich übel aus... für den Dämon.", completion = "Ja, das wird funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[43489] = { id = 43489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Teufelsfeuervorstoß", description = "Ich habe ernüchternde Neuigkeiten, Hochlord.\n\nSeit Häuptling Aponi Lichtmähne, der junge Arator und die Priesterin Delas Mondfang zum Teufelsfeuervorstoß aufgebrochen sind, haben wir nichts mehr von ihnen gehört.\n\nWir müssen erfahren, was mit ihnen geschehen ist...\n\n... und uns auf das Schlimmste gefasst machen.", sourceObjective = "Findet Aponi Lichtmähne am Teufelsfeuervorstoß in Azsuna.", completion = "<Dieses Buch wurde in Aponis Handschrift verfasst. Was ist hier geschehen?>", sourceObjectiveStatus = "unverified-source-field" }
quests[43490] = { id = 43490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aponis Spur", description = "<Dem Buch fehlen mehrere Seiten. In der Nähe seht Ihr Spuren eines Kampfes.>\n\n<Durchsucht die Dämonen in der Nähe nach den fehlenden Seiten. Vielleicht erfahrt Ihr so, was Euren Verbündeten zugestoßen ist.>", sourceObjective = "Findet 8 Seiten aus Aponis Tagebuch und benutzt diese dann, um sie ausfindig zu machen.", completion = "Dem Licht sei Dank, Hochlord. Ich wollte die Hoffnung nicht aufgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[43491] = { id = 43491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündete des Lichts", description = "Sowohl Arator als auch Delas befinden sich noch irgendwo auf diesem elenden Fels... zusammen mit vielen anderen unserer Verbündeten.\n\nWir können sie nicht so einfach zurücklassen, {name}.", sourceObjective = "Rettet 5 Ritter der Silbernen Hand oder Priester der Konklave und rettet Arator den Erlöser sowie Delas Mondfang.", completion = "Ich habe von Aponi Lichtmähne schon viel über Euer Heldentum gehört, Hochlord. Ohne Euch hätten heute viele gute Leute ihr Leben verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[43492] = { id = 43492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Aponi Lichtmähne", sourceObjective = "Hochlord, ich schulde Euch meinen Dank und mein Leben. Ihr lebt wahrhaft nach dem Licht, wie meine Sonnenläufer glauben.\n\nEs ist mir eine Ehre, an Eurer Seite zu kämpfen. Mit Eurer Erlaubnis würde ich gerne weiter für den Orden der Silbernen Hand in die Schlacht ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43493] = { id = 43493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabenwehr: Lord Rabenkrone", description = "Hochlord, wir haben Neuigkeiten über eine Präsenz der Legion in der Rabenwehr.\n\nEs heißt, dass der Nachtelfenkommandant Kur'talos Rabenkrone hinter den Festungsmauern eine riesige Streitmacht zusammenzieht.\n\nNehmt eine Gruppe Eurer mächtigsten Verbündeten und geht diesen Gerüchten auf den Grund, Hochlord. Zur Zeit von Azsharas Herrschaft war Lord Rabenkrone ein äußerst fähiger General. Wir müssen herausfinden, ob an diesen Gerüchten etwas Wahres ist.", sourceObjective = "Bezwingt Lord Kur'talos Rabenkrone in der Rabenwehr.", completion = "Unglaublich, Hochlord. Nachdem die Bedrohung durch die Rabenwehr nun abgewendet ist, können wir uns auf andere Gebiete konzentrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[43494] = { id = 43494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritter der Silbernen Hand", description = "Gute Nachrichten, Hochlord! Wir konnten einen Paladinlehrer namens Kommandant Born anwerben.\n\nEr ist ein strenger Lehrer, aber zu seinen Schülern zählen einige der größten Paladinritter unserer Zeit. Wir können von Glück sagen, dass er uns hilft.\n\nSprecht mit ihm und bildet einen Trupp Ritter der Silbernen Hand aus.", sourceObjective = "Sprecht mit Kommandant Born.", completion = "Wunderbar! Diese Ritter werden dem Orden gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[43495] = { id = 43495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Cadraeus" }
quests[43496] = { id = 43496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die innere Macht", description = "Ich muss mich für den unangekündigten Besuch entschuldigen, {name}. Hättet Ihr einen Augenblick Zeit?\n\nDie Macht in Eurer Waffe ist durch Euren Kampf gegen die Legion angestiegen, doch ich komme nicht über das Gefühl hinweg, dass noch... mehr... darin verborgen liegt. Vielleicht sogar eine gänzlich neue Form!\n\nWir brauchen darüber einfach Gewissheit.\n\nIhr kennt doch den alten blauen Drachen Senegos in Azsuna, nicht wahr? Trefft mich an seinem Ruheplatz, sobald Ihr könnt, und wir besprechen den Rest.", sourceObjective = "Trefft Erzmagier Kalec in der Azurschwingenrast in Azsuna.", completion = "Senegos hat uns für die kommende Reise großzügigerweise seine Hilfe angeboten.\n\nEr hat eine wahrlich gütige Seele.", sourceObjectiveStatus = "unverified-source-field" }
quests[43497] = { id = 43497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion 110 A" }
quests[43498] = { id = 43498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion 110 A" }
quests[43499] = { id = 43499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion 110 H" }
quests[43500] = { id = 43500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion 110 H" }
quests[43501] = { id = 43501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die innere Macht", description = "Ich muss mich für den unangekündigten Besuch entschuldigen, {name}. Hättet Ihr einen Augenblick Zeit?\n\nDie Macht in Eurer Waffe ist durch Euren Kampf gegen die Legion angestiegen, doch ich komme nicht über das Gefühl hinweg, dass noch... mehr... darin verborgen liegt. Vielleicht sogar eine gänzlich neue Form!\n\nWir brauchen darüber einfach Gewissheit.\n\nDer uralte blaue Drache Senegos in Azsuna liegt im Sterben und ist der Schlüssel unserer Reise. Ihr müsst ihm helfen. Ich werde Euch in seinem Reich treffen, sobald es mir möglich ist.", sourceObjective = "Schließt den Handlungsstrang \"Verteidigung der Azurschwingenrast\" in Azsuna ab und trefft Euch dann mit Erzmagier Kalec in der Azurschwingenrast.", completion = "Senegos hat uns für die kommende Reise großzügigerweise seine Hilfe angeboten.\n\nEr hat eine wahrlich gütige Seele.", sourceObjectiveStatus = "unverified-source-field" }
quests[43502] = { id = 43502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit der Veränderung", description = "Es ist so weit.\n\nDer Arcan'dor bereitet sich auf seine Reife vor. Im Zuge eines letzten Wachstumsschubes wird sich uns dieses Geschenk in vollem Umfang offenbaren.\n\nWir müssen jetzt die Leylinienzuleitung vorbereiten.", sourceObjective = "Sprecht mit Arkanistin Valtrois.", completion = "Unser Bäumchen scheint einen tüchtigen Durst zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[43503] = { id = 43503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die innere Macht", description = "Hättet Ihr einen Augenblick Zeit, <Beschwörer/Beschwörerin>?\n\nDie Macht in Eurer Waffe ist mit Eurem Kampf gegen die Legion angestiegen, doch ich komme nicht über das Gefühl hinweg, dass noch... mehr... tief darin verborgen liegt. Vielleicht sogar eine gänzlich neue Form!\n\nWir brauchen darüber einfach Gewissheit.\n\nIhr kennt doch den alten blauen Drachen Senegos in Azsuna, nicht wahr? Trefft mich an seinem Ruheplatz, sobald Ihr könnt, und wir besprechen den Rest.", sourceObjective = "Trefft Erzmagier Kalec in der Azurschwingenrast in Azsuna.", completion = "Senegos hat uns für die kommende Reise großzügigerweise seine Hilfe angeboten.\n\nEr hat eine wahrlich gütige Seele.", sourceObjectiveStatus = "unverified-source-field" }
quests[43505] = { id = 43505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die innere Macht", description = "Hättet Ihr einen Augenblick Zeit, <Beschwörer/Beschwörerin>?\n\nDie Macht in Eurer Waffe ist mit Eurem Kampf gegen die Legion angestiegen, doch ich komme nicht über das Gefühl hinweg, dass noch... mehr... darin verborgen liegt. Vielleicht sogar eine gänzlich neue Form!\n\nWir brauchen darüber einfach Gewissheit.\n\nDer uralte blaue Drache Senegos in Azsuna liegt im Sterben und ist der Schlüssel unserer Reise. Ihr müsst ihm helfen. Ich werde Euch in seinem Reich treffen, sobald es mir möglich ist.", sourceObjective = "Schließt den Handlungsstrang \"Verteidigung der Azurschwingenrast\" in Azsuna ab und trefft Euch dann mit Erzmagier Kalec in der Azurschwingenrast.", completion = "Senegos hat uns für die kommende Reise großzügigerweise seine Hilfe angeboten.\n\nEr hat eine wahrlich gütige Seele.", sourceObjectiveStatus = "unverified-source-field" }
quests[43506] = { id = 43506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabenwehr: Größere Macht", description = "Mit der gewaltigen Macht der Runensteine kann Hymdall kurzfristig einen Riss in die dämonischen Welten öffnen, aber das ist nicht genug.\n\nDie Legion bedient sich dunkler Magie, um ihren Aufenthaltsort in diesen fernen Welten zu verschleiern. Besorgt einen großen Runenstein, damit Hymdall unsere Feinde auf der anderen Seite des Kosmos anvisieren kann.", sourceObjective = "Besiegt Lord Kur'talos Rabenkrone und besorgt einen großen dämonischen Runenstein von Dantalionax in der Rabenwehr.", progress = "Habt Ihr den Runenstein, den wir benötigen, {name}?", completion = "Es ist vollbracht. Lasst uns die Valarjar auf eine glorreiche Schlacht vorbereiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[43507] = { id = 43507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looted Priest Altar" }
quests[43508] = { id = 43508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefangene Meisterspion", description = "Wir müssen uns beeilen, solange sie vom Täuschungsmanöver abgelenkt sind. Mathias Shaw wird direkt im Süden gefangen gehalten, irgendwo in den unteren Ebenen der Hallen der Dunkelung.\n\nSchnell, {name}. Wir müssen los!", sourceObjective = "Folgt Taoshi in die Hallen der Dunkelung zum Gefängnis von Mathias Shaw.", completion = "Schnell, {name}. Wir müssen ihn von hier fortschaffen, bevor die Dämonen Alarm schlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43509] = { id = 43509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Odyns Herausforderung", description = "Odyn selbst hat eine Nachricht geschickt. Er und seine Krieger warten in den Hallen der Tapferkeit auf würdige Anwärter.\n\nBezwingt die Champions in den Hallen der Tapferkeit und der Ruhm ist Euer.", sourceObjective = "Bezwingt Odyn in den Hallen der Tapferkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[43510] = { id = 43510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seal of Fate: Class Hall" }
quests[43511] = { id = 43511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalec Arrives" }
quests[43512] = { id = 43512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ana-Mouz" }
quests[43513] = { id = 43513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Na'zak das Scheusal" }
quests[43514] = { id = 43514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine selbstherrliche Vergangenheit", description = "Die Magie des Herzens ist durch mächtige Schutzzauber auf Azsharas Elite abgestimmt. Wenn wir jetzt versuchen, seine Macht anzuzapfen, würde das mit unserem Tod enden.\n\nEs könnte allerdings einen Weg geben, wie wir die Zauberschutze umgehen können.\n\nPrinz Farondis und sein Hof gehörten einst zu Azsharas Reich und halten immer noch an den Andenken ihrer schäbigen Vergangenheit fest. Darunter befindet sich sicherlich ein Gebräu der Selbstherrlichen, dem man nachsagt, dass es das Gefolge der Königin noch stärker ihrem Willen unterwirft.\n\nVersucht doch, dem Hof eine Flasche abzuluchsen.", sourceObjective = "Beschafft ein Gebräu der Selbstherrlichen von Veridis Fallon.", progress = "Wahrscheinlich wird es nicht leicht, Farondis' Gefolge das Gebräu abzuluchsen. Einige klammern sich immer noch verzweifelt an ihr früheres Leben.", completion = "Gut gemacht. Wir können es gegen die Magie verwenden, die das Herz beschützt.", sourceObjectiveStatus = "unverified-source-field" }
quests[43517] = { id = 43517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Die Macht des Gefallenen", description = "Sobald wir die richtigen Instrumente haben, können wir das Herz dazu verwenden, Euer Artefakt mit großer Macht zu tränken. Wir benötigen nur eine Quelle.\n\nTief im Finsterherzdickicht liegt der uralte Eichenherz, der einst ein großartiger und mächtiger Beschützer von Shaladrassil war. Bedauerlicherweise ist er dem Alptraum anheimgefallen, wie so viele seiner Art.\n\nAls die Dunkelheit sich in ihm festgesetzt hat, manifestierte sich eine Essenz der Verderbnis. Ich bitte Euch, diese Essenz zu beschaffen, damit wir von ihrer Macht profitieren und den edlen Eichenherz zur Ruhe betten können.", sourceObjective = "Beschafft eine verderbte Essenz von Eichenherz und besiegt den Schemen von Xavius im Finsterherzdickicht auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Habt Ihr die Essenz?", completion = "Das Urtum hat seinen Frieden wiedergefunden.\n\nMöge sein Opfer nicht vergeblich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[43518] = { id = 43518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Härtende Dunkelheit", description = "Ich habe keine Zweifel an Senegos' Plan, aber ich habe Bedenken, was die Unbeständigkeit des Herzens angeht, besonders, wenn man es mit Alptraumenergie kombiniert.\n\nTrotz seines Namens wird das Blut von Sargeras von meisterhaften Handwerkern oft als Härtungsmittel verwendet. Ich glaube, es würde auch bei unserem Ritual funktionieren.\n\nIhr solltet während Eurer Reisen die Augen danach offenhalten. Wir werden eine beträchtliche Menge brauchen, damit alles glatt verläuft.", sourceObjective = "Beschafft 5 Einheiten Blut von Sargeras.", progress = "Es ist manchmal schwer zu extrahieren und ich möchte nichts dem Zufall überlassen.", completion = "Fantastisch! Das wird auf jeden Fall reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43519] = { id = 43519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lichte Stärke", description = "Wir haben alles, was wir brauchen, {name}.\n\nSobald Ihr bereit seid, hebt Euer Artefakt hoch und kanalisiert seine Energie auf das Herz von Zin-Azshari, um die in der Alptraumessenz gespeicherte Macht sicher zu absorbieren.\n\nIch werde das von Euch bereitgestellte Blut benutzen, um sicherzustellen, dass das Ritual sicher abläuft.", sourceObjective = "Absorbiert die Macht der verderbten Essenz mithilfe des Herzens von Zin-Azshari.", progress = "Dies ist nur der erste Schritt, um das wahre Potential freizusetzen, das sich tief in Eurem Artefakt verborgen hält, aber dennoch ist dies ein aufregender Meilenstein.", completion = "Gut gemacht! Alles ist wie geplant verlaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43520] = { id = 43520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Alptraum: In den Alpträumen", description = "Wir müssen alles Mögliche tun, damit der Alptraum wirklich nie wieder im Smaragdgrünen Traum schwärt.\n\nDie Entartung namens Il'gynoth befindet sich im Herzen der Verderbnis, eine lebendige, sich windende Manifestation der Schrecken, denen Ihr auf Eurer Reise an jeder Ecke begegnen werdet.\n\nIch bitte Euch, ihn ein für alle Mal zu zerstören... und den Alptraumfürsten Xavius gleich mit.\n\nSobald es vollbracht ist, bringt mir ein kleines Stück von beiden. Wir können sie untersuchen, um herauszufinden, warum der Alptraum so schnell gewachsen ist.", sourceObjective = "Beschafft eine Todesblickiris und das Horn des Alptraumfürsten aus dem Smaragdgrünen Alptraum auf dem Schwierigkeitsgrad 'Normal' oder höher.", progress = "Habt Ihr es hinter Euch gebracht?", completion = "Das ist weit mehr, als wir benötigen.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[43521] = { id = 43521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Alptraum: Die Essenz der Macht", description = "Jetzt, da wir die Möglichkeiten des Herzens besser verstehen, wird es Zeit, uns sein wahres Potenzial zunutze zu machen.\n\nIm Smaragdgrünen Alptraum findet Ihr Kreaturen, die es gar nicht geben dürfte... Monster, die nichts mit dem zu tun haben, wofür der Traum steht.\n\nSie widerstreben einfach allem, was dem grünen Schwarm heilig ist.\n\nJeder dieser Unholde trägt eine verderbte Essenz in sich, so wie auch Eichenherz es tat... nur noch stärker. Sammelt alle, derer Ihr habhaft werden könnt, und wir werden ihre eigene Verderbnis gegen sie wenden.", sourceObjective = "Sammelt 10 verderbte Essenzen aus dem Smaragdgrünen Alptraum auf dem Schwierigkeitsgrad 'Normal' oder höher.", progress = "Die vor Euch liegende Aufgabe ist nicht leicht, aber ich vertraue auf Eure Fähigkeiten.", completion = "Eure Tapferkeit kann es mit der meines eigenen Volkes aufnehmen.\n\nGut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[43522] = { id = 43522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenzverbrauch", description = "{name}, Ihr hebt Euer Artefakt wie zuvor und kanalisiert seine Energie auf das Herz von Zin-Azshari, damit wir die Macht der Essenz, die Ihr gesammelt habt, entfesseln können.\n\nMacht Euch keine Sorgen. Wir haben immer noch genug von dem Blut, das Ihr gesammelt habt, um das Ritual stabilisieren zu können.", sourceObjective = "Absorbiert die vereinte Macht der verderbten Essenzen mithilfe des Herzens von Zin-Azshari.", progress = "Nach allem, was Ihr für meinen Schwarm getan habt, ist das nur ein kleiner Gefallen als Entschädigung.", completion = "Das ist alles, was ich für Euch tun kann, Winzling. Wenn Ihr noch mehr Macht wollt, müsst Ihr sie woanders suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43523] = { id = 43523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückgezahlte Schuld", description = "Die Mondwache hat vor vielen Jahren im Krieg der Ahnen gegen die Legion gekämpft. Ihre detaillierten Kenntnisse über unsere Feinde wären von unschätzbarem Wert für unsere Sache.\n\nSie sind in Shal'Aran zurückgeblieben, nachdem Ihr Thalrenus und die Seinen gerettet habt. Sollen wir sie aufsuchen und sehen, was sie ausrichten können?", sourceObjective = "Trefft Erzmagier Kalec in Shal'Aran in Suramar.", completion = "Sprechen wir mit Thalrenus, um unseren Schlachtplan zu erörtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[43524] = { id = 43524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hof der Sterne: Herausragende Literatur", description = "Von allen Büchern, warum ausgerechnet dieses?! Oh, Mutter Mond, ich bin nur ein argloser Dummkopf.\n\nEntschuldigt, Ihr wisst nicht, wovon ich rede.\n\nIch habe meine Erstausgabe von \"Zauberschutze, Siegel und die Lebensart der Nachtgeborenen\" einem lieben Freund geliehen... nun, früheren Freund, sollte ich wohl sagen... kurz vor dem Verrat.\n\nWie das Schicksal es so will, befindet sich in dem Buch eine Beschwörungsformel, die ich für meinen Beitrag zum Ritual brauche.\n\nBitte holt es mir wieder, aber seid vorsichtig. Es ist ziemlich wertvoll!", sourceObjective = "Sucht nach Lothrius' Erstausgabe von \"Zauberschutze, Siegel und die Lebensart der Nachtgeborenen\" im Hof der Sterne auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Habt Ihr es gefunden? Oh, bitte sagt mir, dass Ihr es gefunden habt!", completion = "Das ist es! Oh, ich danke Euch, {name}. Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[43525] = { id = 43525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Verlies der Wächterinnen: Ausborgen, ohne zu fragen", description = "Die schwer fassbaren Wächterinnen betreiben ein riesiges geheimes Gefängnis tief unter den Bergen von Azsuna, in dem sich alle möglichen widerlichen Kreaturen befinden.\n\nVielleicht wäre \"haben betrieben\" der richtigere Ausdruck.\n\nDas bietet uns eine einmalige Gelegenheit. Die Wächterinnen haben mächtige Eindämmungskristalle benutzt, um jeden Gefangenen in seiner Zelle einzuschließen. Wenn davon noch einige unversehrt sind, können wir sie dazu benutzen, die Macht des Herzens sicher einzudämmen.\n\nSie werden sie dort bestimmt nicht mehr brauchen.", sourceObjective = "Beschafft einen Eindämmungskristall aus dem Verlies der Wächterinnen auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Schon Glück gehabt?", completion = "Ausgezeichnet. Das wird ziemlich gut funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[43526] = { id = 43526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein echter Test", description = "Vizuuls Runenbindungen sind noch stärker, als ich gedacht hatte. Das ist nichts Schlimmes, mehr Kraft ist auf jeden Fall willkommen, aber es gibt dadurch noch mehr Potenzial für Katastrophen, wenn die Zaubermatrix irgendwie instabil wird.\n\nWir sollten eigentlich in der Lage sein, die Teufelsenergie mit einem Eindämmungsfeld in Schach zu halten, für das wir den von Euch entdeckten Weltenzeitwinder benutzen werden... Aber Ihr solltet trotzdem die Augen offenhalten... nur für den Fall.", sourceObjective = "Absorbiert die Macht der verzerrten Runenbindungen mithilfe des Herzens von Zin-Azshari.", completion = "Es... Es tut mir so leid, {name}. Ich war so sicher, es würde funktionieren...", sourceObjectiveStatus = "unverified-source-field" }
quests[43527] = { id = 43527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung der Wache", description = "Die Mondwache bestand einst aus den mächtigsten Zauberern Azeroths. Die meisten glauben, dass sie nach dem Krieg der Ahnen zerschlagen wurde, aber anscheinend hat sie in ihrer uralten Festung in Suramar überlebt!\n\nIch denke, sie könnte ein wertvoller Verbündeter für unsere Suche sein, wenn sie immer noch Gegner der Legion ist.\n\n{name}, wenn Ihr das, was von der Wache noch übrig ist, retten könnt, werde ich daran arbeiten, dass der Rat der Sechs uns weitere Hilfe gewährt.", sourceObjective = "Schließt den Handlungsstrang \"Die Mondwachenfestung\" in Suramar ab und trefft dann Erzmagier Kalec in Shal'Aran.", completion = "Anscheinend haben wir neue Verbündete gefunden. Lasst uns einen Schlachtplan schmieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[43528] = { id = 43528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Planung des Angriffs", description = "Dank Eurer unermüdlichen Anstrengungen kann sich das Herz von Zin-Azshari nun gegen die geballte Macht der Legion behaupten. Das Ziel unserer langen Reise hat seit dem ersten Schritt einen dunklen Schatten auf uns geworfen, die Nachtfestung, nun eine Bastion von Gul'dan höchstpersönlich.\n\nWir müssen einen Weg hinein finden.\n\nIch arbeite fieberhaft mit dem Rat der Sechs an einer Lösung. Sobald wir einen Zugang gefunden haben, sollten wir unsere Kräfte wieder mit der Mondwache in Shal'Aran vereinen. Wir sind weiterhin auf ihre Fähigkeiten angewiesen.", sourceObjective = "Wartet, dass sich die Nachtfestung für Euch öffnet, und trefft Euch dann mit Erzmagier Kalec in Shal'Aran.", completion = "Wir haben einen rückseitigen Eingang in die Nachtfestung gefunden, der den Armeen am Vordereingang etwas Erleichterung verschaffen könnte.\n\nMit Betonung auf \"etwas\".", sourceObjectiveStatus = "unverified-source-field" }
quests[43530] = { id = 43530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Größenwahn", description = "Großmagistrix Elisande und ihre Gefolgsleute haben den Verstand verloren. Sie glauben tatsächlich, dass ihr Bündnis mit der Legion in etwas anderem endet als ihrem eigenen Niedergang!\n\nIch fürchte, sie selbst sind nicht mehr zu retten, aber sie haben mächtige Gegenstände, die wir nutzen können, um das Herz von Zin-Azshari mit ihrer Macht zu erfüllen.\n\nStellt sicher, dass Ihr bei Eurem Angriff auf die Nachtfestung den Energiekern des verrückten Konstrukts, Trilliax, und das Zauberbuch der Großmagistrix selbst erbeutet.\n\nViel Glück.", sourceObjective = "Erbeutet den Kern von Trilliax und den Folianten der Jahrtausende von Großmagistrix Elisande in der Nachtfestung auf dem Schwierigkeitsgrad 'Normal' oder höher.", progress = "Ich bitte Euch um mehr, als ich möchte, aber es gibt keinen anderen Weg.", completion = "<Beim Anblick des Folianten der Jahrtausende bekommt Thalrenus große Augen.>\n\nWenn Elisande zur Vernunft gekommen ist... gibt es ja vielleicht doch noch Hoffnung für die Wache.", sourceObjectiveStatus = "unverified-source-field" }
quests[43531] = { id = 43531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: In die Nachtfestung", description = "Unsere Arbeit ist fast abgeschlossen. Jetzt, wo das Herz sicher Macht aus Teufelsmagie absorbieren kann, brauchen wir die stärkste Quelle an Teufelsmagie, die wir in die Hände bekommen können.\n\nGul'dan hat die Nachtgeborenenelite zurück zur Nachtfestung gerufen, um ihm zu helfen. Der Sturm aus Teufelsenergie über dem Palast ist tief in ihre Wesen selbst und sogar in die kristallisierten Teile des Nachtbrunnens, die viele bei sich tragen, eingesickert.\n\nDiese Splitter sind genau, was wir brauchen, {name}. Sammelt während Eures Angriffs so viele davon ein wie möglich.", sourceObjective = "Sammelt 8 Nachtsplitter von der Nachtfestung auf dem Schwierigkeitsgrad 'Normal' oder höher.", progress = "Wie viele Nachtsplitter konntet Ihr erbeuten?", completion = "<Kalec durchstöbert den Haufen der Nachtsplitter.>\n\nJa, die sind perfekt! Jetzt gibt es nur noch eines, was wir brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43532] = { id = 43532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Die Dunkelheit ruft", description = "Bevor wir mit dem Ritual beginnen, muss ich Euch um einen letzten Gefallen bitten, {name}.\n\nIhr müsst Gul'dan seiner gerechten Strafe zuführen.\n\nSeine Lügen, seine Täuschungen und sein Verrat müssen ein Ende haben. Nichts davon wird ihn jetzt noch retten.\n\nWenn Ihr alles erledigt habt, nehmt eins seiner herbeigezauberten Augen. Wenn wir seine Macht für das Gute einsetzen, ist das nur gerecht.", sourceObjective = "Bringt eines von Gul'dans Augen zu Erzmagier Kalec auf dem Schwierigkeitsgrad 'Normal' oder höher.", progress = "Habt Ihr es hinter Euch gebracht?", completion = "Lasst uns keine weitere Zeit verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[43533] = { id = 43533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gleichgewicht der Kräfte", description = "Endlich können wir die Früchte Eurer Arbeit ernten.\n\nLothrius erwähnte einen Ort tief in der früheren Mondwachenfestung, an dem die neuen Wachen mit unglaublicher Macht erfüllt werden. Das wäre genau der richtige Ort, um die Macht der von Euch gesammelten Nachtsplitter anzuzapfen und zu verstärken.\n\nSammelt Eure Siebensachen und trefft mich dort, wenn Ihr bereit seid. Wir werden das Herz benutzen, um endlich die in Eurem Artefakt enthaltene Macht zum Vorschein zu bringen.", sourceObjective = "Absorbiert die vereinte Macht der Nachtsplitter und des Auges von Gul'dan mithilfe des Herzens von Zin-Azshari am Mondtiegel.", completion = "Die neue Form Eures Artefakts ist sogar noch großartiger, als ich es mir vorgestellt hatte.\n\nBitte nehmt die Überreste des Herzens als Zeichen meiner Dankbarkeit für solch ein wunderbares Abenteuer. Darin befindet sich immer noch einiges an Macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[43534] = { id = 43534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut von Sargeras", description = "Wir werden ein mächtiges Reagenz benötigen, um die Magie in unsere Waffen und Rüstungen zu binden. Das Blut von Sargeras ist ein seltenes Material, mit dem genau dies gelingen könnte.\n\nWir brauchen dafür aber eine ganze Menge. Bringt mir also so viel davon, wie Ihr nur könnt.", sourceObjective = "Sammelt 3 Blut von Sargeras.", progress = "Habt Ihr schon Blut von Sargeras gefunden?", completion = "Ja, das ist genau, was wir brauchen, um unsere Vorbereitungen abzuschließen. Die Beschaffung war sicherlich nicht einfach. Ich danke Euch, Hochlord.", sourceObjectiveStatus = "unverified-source-field" }
quests[43535] = { id = 43535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übersetzung: Gefahr!", description = "<Delas schmiert Teufelsblut über die Seiten des Lexikons. Fremdartige Symbole lodern plötzlich auf, und fieberhaft beginnt sie, alles niederzuschreiben.>\n\nAch du liebe Zeit... Das sind detaillierte Aufzeichnungen über die Invasionsstreitkräfte der Legion am Teufelsfeuervorstoß. Sie wollen ein Portal öffnen, das direkt in ihre Dämonenwelt Niskara führt! Das ist wirklich ernst. Wir müssen sofort unsere Verbündeten benachrichtigen.\n\nWenn Ihr zur Kapelle des Hoffnungsvollen Lichts zurückkehrt, dürfte ich Euch dann begleiten? Ich würde gern meine Dienste anbieten.", sourceObjective = "Sprecht mit Aponi Lichtmähne im Sanktum des Lichts.", completion = "Vielen Dank, dass Ihr Delas mitgebracht habt, {name}. Ich wusste, sie kann uns helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43539] = { id = 43539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salanar der Reiter", description = "Die Vier Reiter benötigen perfekte Streitrösser. Das wird keine leichte Aufgabe.\n\nDer nächste Schritt unserer Kampagne führt uns in das Schattenreich.\n\nDas Ziel der Mission ist, Salanar den Reiter zu finden und ihn nach Acherus zu rufen. Salanar ist der Anführer der Dunklen Reiter.\n\nIhr könnt sofort jemanden mit dieser Mission beauftragen.", sourceObjective = "Schließt die Mission \"Salanar der Reiter\" ab.", completion = "Die Champions der Schwarzen Klinge, die in das Schattenreich entsandt wurden, sind erfolgreich nach Acherus zurückgekehrt.\n\nSalanar der Reiter wird in Kürze eintreffen und mit den Vorbereitungen für die Schreckensrösser beginnen. Ihr solltet Euch mit ihm treffen, sobald er hier ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[43540] = { id = 43540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gedanken des Feindes", description = "Die Kerkermeister der Dämonen haben über eine bevorstehende Invasion gesprochen. Ihre Armee sammelt sich für ein wirklich großes Vorhaben, und das macht mir große Sorgen.\n\nWir müssen so viel wie möglich über ihre Pläne herausfinden.", sourceObjective = "Sucht nach Informationen der Legion, der Sternenkarte und dem Abbild von Velen und vernichtet dann die Brutkönigin Aramis.", completion = "Die Legion will also das Hauptquartier der Priester angreifen? Gut, dass Ihr diese Information rechtzeitig beschaffen konntet, Hochlord.\n\nEs ergibt durchaus Sinn, dass die Legion den Propheten Velen und seine Anhänger als Ziel auswählt. Wir müssen Balnazzars Pläne vereiteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[43541] = { id = 43541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsam sind wir stark", description = "Ich bin froh, dass Ihr unversehrt zurück seid, Hochlord. Delas Mondfang ist ebenfalls mit Vertretern der Konklave eingetroffen.\n\nDie Priester wollen sich über den Netherlichttempel beraten, den Sitz ihrer Macht tief im Wirbelnden Nether.\n\nWie Ihr ja beide herausgefunden habt, sucht die Legion nun schon eine ganze Weile nach ihnen und nun... hatte ihre Suche Erfolg.\n\nDie Silberne Hand ist bereit, sie anzuhören. Wollt Ihr Euch nicht zu ihnen gesellen, Hochlord?", sourceObjective = "Sprecht mit Delas Mondfang und lauscht den Worten des Kriegsrates.", progress = "Delas ist hier, um für die Konklave zu sprechen.", completion = "Ich glaube, Ihr habt eine weise Entscheidung getroffen, Hochlord. Wir werden bei der Verteidigung des Netherlichttempels helfen und Balnazzar eine Falle stellen.\n\nDie Priester der Konklave sind mächtige Verbündete. Gemeinsam haben wir vielleicht sogar eine Chance gegen Balnazzar.", sourceObjectiveStatus = "unverified-source-field" }
quests[43542] = { id = 43542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Tideclaw" }
quests[43545] = { id = 43545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabenwehr: Der Herr der Rabenwehr", description = "Während unsere Champions die Überreste der Rabenwehr untersuchten, gerieten sie in einen Hinterhalt! Der Herr der Rabenwehr hat sich offenbar mit der Legion zusammengetan.\n\nWir brauchen Eure Hilfe, um seine immer größer werdende Armee zu besiegen und ihn zur Strecke zu bringen.", sourceObjective = "Bezwingt Lord Kur'talos Rabenkrone in der Rabenwehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[43546] = { id = 43546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Alptraum: Il'gynoth", description = "Unsere Champions haben die Quelle der Verderbtheit entdeckt. Die Legion ist in den Smaragdgrünen Traum eingefallen, und wenn wir unsere Bemühungen nicht darauf konzentrieren, sie aufzuhalten, wird das nur der Anfang der Verderbnis sein. Sie muss jetzt aufgehalten werden.", sourceObjective = "Bezwingt Il'gynoth im Smaragdgrünen Alptraum.", progress = "Wie gestalten sich die Herausforderungen im Smaragdgrünen Alptraum?", completion = "Habt Ihr den Smaragdgrünen Alptraum bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[43547] = { id = 43547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Alptraum: Il'gynoth", description = "Unsere Champions haben die Quelle der Verderbtheit entdeckt. Die Legion ist in den Smaragdgrünen Traum eingefallen, und wenn wir unsere Bemühungen nicht darauf konzentrieren, sie aufzuhalten, wird das nur der Anfang der Verderbnis sein. Sie muss jetzt aufgehalten werden.", sourceObjective = "Bezwingt Il'gynoth im Smaragdgrünen Alptraum.", completion = "Habt Ihr den Smaragdgrünen Alptraum bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[43548] = { id = 43548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Alptraum: Il'gynoth", description = "Unsere Champions haben die Quelle der Verderbtheit entdeckt. Die Legion ist in den Smaragdgrünen Traum eingefallen, und wenn wir unsere Bemühungen nicht darauf konzentrieren, sie aufzuhalten, wird das nur der Anfang der Verderbnis sein. Sie muss jetzt aufgehalten werden.", sourceObjective = "Bezwingt Il'gynoth im Smaragdgrünen Alptraum.", progress = "Wie gestalten sich die Herausforderungen im Smaragdgrünen Alptraum?", completion = "Habt Ihr den Smaragdgrünen Alptraum bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[43549] = { id = 43549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Alptraum: Il'gynoth", description = "Unsere Champions haben die Quelle der Verderbtheit entdeckt. Die Legion ist in den Smaragdgrünen Traum eingefallen, und wenn wir unsere Bemühungen nicht darauf konzentrieren, sie aufzuhalten, wird das nur der Anfang der Verderbnis sein. Sie muss jetzt aufgehalten werden.", sourceObjective = "Bezwingt Il'gynoth im Smaragdgrünen Alptraum.", progress = "Wie gestalten sich die Herausforderungen im Smaragdgrünen Alptraum?", completion = "Habt Ihr den Smaragdgrünen Alptraum bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[43550] = { id = 43550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hof der Sterne: In den Hof der Sterne", description = "Das Wetter ist einfach perfekt für ein Fest, nicht wahr?\n\nBegebt Euch zum Hof der Sterne. Dort könnt Ihr vielleicht die Großmagistrix persönlich dabei erblicken, wie sie all die Adeligen von der Notwendigkeit der vielen Legionspatrouillen überzeugt.", sourceObjective = "Bezwingt Berater Melandrus am Hof der Sterne.", sourceObjectiveStatus = "unverified-source-field" }
quests[43551] = { id = 43551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Ins Finsterherzdickicht", description = "Im Schatten von Shaladrassil vergrößert Xavius seinen Einfluss, um den ehemals reinen Hain der Druiden zu unterjochen und zu verderben.\n\nAber das ist noch nicht alles. Xavius hat sich eine Trophäe aus den Reihen der Druiden geholt und wird seine Rache langsam und grausam genießen. Wir sollten zum Finsterherzdickicht aufbrechen und seine teuflischen Pläne vereiteln.", sourceObjective = "Bezwingt den Schemen von Xavius im Finsterherzdickicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[43552] = { id = 43552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: In das Auge Azsharas", description = "Unsere Untersuchung hat ergeben, dass die Naga auf persönlichen Befehl von Königin Azshara ein mächtiges Wesen beschwören wollen, das Azsharas Macht auf die Verheerten Inseln entfesseln wird.\n\nBegebt Euch zum Auge Azsharas und haltet das Ritual auf.", sourceObjective = "Bezwingt Azsharas Zorn im Auge Azsharas.", sourceObjectiveStatus = "unverified-source-field" }
quests[43553] = { id = 43553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund: In den Seelenschlund", description = "Unsere Späher berichten, dass verdammte Vrykul gezwungen werden, als Gefangene auf der Naglfar zu segeln, einem Schiff des Todes.\n\nBegebt Euch zum Seelenschlund und stellt Helya, bevor ihr noch mehr arme, unglückselige Seelen zum Opfer fallen.", sourceObjective = "Bezwingt Helya im Seelenschlund.", sourceObjectiveStatus = "unverified-source-field" }
quests[43554] = { id = 43554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharions Hort: In den Hort", description = "Laut unseren Spähern haben die Drogbar nicht nur ein Titanenrelikt gefunden, sondern auch eine Armee aufgestellt, die groß genug ist, um eine Bedrohung für die gesamte Oberwelt darzustellen.\n\nBegebt Euch in den Untergrund und haltet den Unterkönig auf, bevor er seine Drogbararmee in Marsch setzt.", sourceObjective = "Bezwingt Dargrul in Neltharions Hort.", sourceObjectiveStatus = "unverified-source-field" }
quests[43555] = { id = 43555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Arkus: In den Arkus", description = "Der Arkus ist viel größer, als wir gedacht hatten, und birgt viele Gefahren. Wenn wir überhaupt eine Chance haben wollen, die Stadt einzunehmen, müssen wir uns zuerst um den Untergrund kümmern.\n\nBetretet den Arkus und vernichtet sämtliche Feinde.", sourceObjective = "Bezwingt Berater Vandros im Arkus.", sourceObjectiveStatus = "unverified-source-field" }
quests[43556] = { id = 43556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Verlies der Wächterinnen: Ins Verlies der Wächterinnen", description = "Im Verlies der Wächterinnen ist es schlimmer, als wir gedacht hatten. Die Gefangenen haben sich selbst zu Wärtern gemacht und das Verlies vollständig übernommen. Laut unseren Berichten könnte sich Cordana Teufelsang ebenfalls dort aufhalten.\n\nBegebt Euch zum Verlies der Wächterinnen und läutert den Ort von allem Bösen.", sourceObjective = "Bezwingt Cordana Teufelsang im Verlies der Wächterinnen.", progress = "Wie gestaltet sich das Verlies der Wächterinnen?", completion = "Konntet Ihr das Verlies der Wächterinnen bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[43557] = { id = 43557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf die Violette Festung: In die Violette Festung", description = "In der Violetten Festung befinden sich einige der mächtigsten Diener des Lichkönigs und sie könnte jeden Augenblick von Agenten der Legion überrannt werden. Wir müssen uns dort hinbegeben und die Dämonen vernichten, bevor sie die Gefangenen befreien.", sourceObjective = "Bezwingt den Anführer des Sturms auf die Violette Festung.", sourceObjectiveStatus = "unverified-source-field" }
quests[43558] = { id = 43558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bindungen des Windlords", description = "Jetzt, da Donneraan erneut der Lord des Himmelswalls ist, könnten wir vielleicht im Austausch gegen diese verfluchten Bindungen ein Abkommen treffen. Aber denkt daran: Eine allein ist nicht ausreichend.\n\nKehrt mit beiden Bindungen und ausreichend mächtigem Erz, um sie zu binden, zu mir zurück. Dann werde ich Euch eine Audienz bei Donneraan dem Windlord verschaffen.", sourceObjective = "Besorgt beide Bindungen des Windlords und 10 Stücke Infernoschwefel.", progress = "Ja, {race}?", completion = "Ihr habt es also geschafft, mit den Bindungen zurückzukehren. Der Feuerlord wird nicht gerade erfreut sein, sie verloren zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[43560] = { id = 43560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audienz beim Windlord", description = "Ich habe mein Versprechen gehalten. Donneraan der Windlord wartet.\n\nIhr solltet wissen, dass der Windlord sich nicht täuschen lassen wird, wenn Verrat in Eurem Herzen wohnt. Schweigt und vielleicht wird Eure Audienz glücklich verlaufen.", sourceObjective = "Tretet vor Donneraan.", completion = "Die Bindungen gehören jetzt mir. Zum richtigen Zeitpunkt wird der Windlord eingekerkert werden, so wie ich es einst war. Doch jetzt ist es noch nicht so weit.\n\nDies ist Eure Belohnung, ein kleines Fragment meiner Macht. Setzt es auf Euren Klingen frei, {race}, und Ihr werdet bekommen, wonach es Euch verlangt.", sourceObjectiveStatus = "unverified-source-field" }
quests[43561] = { id = 43561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich glaube, ich kann fliegen!", description = "Halten wir uns nicht mit Erklärungen auf, wie es dazu kommen konnte. Wisst einfach nur, dass ich DEN Fluchtplan für all dieses... dieses... <Er wirft einen Blick auf seine handgemachte Kleidung und dann auf einen ekelhaften Haufen in der Nähe.>\n\nDieser Ort stinkt furchtbar! Aber Ihr könnt helfen!\n\nDiese Federn hier sind ein wichtiger Teil meines Fluchtplans. Wenn es Euch nichts ausmacht... Ich bin sicher, es gibt genug für uns beide!", sourceObjective = "Sammelt 6 gemauserte Federn für Snikarus Dengelflug.", sourceObjectiveStatus = "unverified-source-field" }
quests[43562] = { id = 43562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles, was wir haben", description = "Der Arcan'dor konsumiert unglaubliche Mengen Energie.\n\nSelbst die voll ausgelastete Leylinienzuleitung könnte vielleicht nicht ausreichen.\n\nLasst uns als Erstes sicherstellen, dass alle verfügbaren Leylinienleitungen nach Shal'Aran auch aktiv sind.\n\nIch kann dann versuchen, die Ausgangsleistung zu erhöhen, um diese unsägliche Pflanze zufriedenzustellen.", sourceObjective = "Aktiviert alle Leylinienzuleitungen in Suramar und sprecht dann mit Valtrois.", completion = "Wir müssen auf drastische Maßnahmen zurückgreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43563] = { id = 43563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ephemerer Manasturmprojektor", description = "Oculeths Theorie ist solide. Gewagt, aber solide.\n\nEin kleines Warpfeld könnte Mana aus der Umgebung in der Leitung einfangen und anregen. Wir erhalten dann einen ähnlichen Manasturm, wie den, der durch Arcan'dors Gleichgewichtsverlust entstanden war.\n\nIch kann einen Apparat bauen, um das Warpfeld zu erzeugen, aber ich brauche Materialien.\n\nGanz besonders warpresistente Legierungen wie die Panzerungsplatten von hoch entwickelten Sicherheitskonstrukten aus dem Adelsviertel.\n\nDiese Konstrukte sind tödlich. Wenn Euch jemand einen Gefallen schuldet, wäre jetzt die Zeit, ihn einzufordern.", sourceObjective = "Sammelt 4 warpresistente Panzerungen von Chronarchverteidigern.", progress = "Ohne diese Panzerplatten würde es den E.M.P. innerhalb von Sekunden zerreißen.", completion = "Damit wird es gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43564] = { id = 43564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flusskontrolle", description = "Wenn alles nach Plan läuft, wird der Manasturm die Leylinie auflodern lassen und einen großen Energieschub durch den Arkus schicken.\n\nDamit dieser Schub Shal'Aran erreicht, müssen wir alle Schnittstellen unterwegs versiegeln. Wenn wir auch nur einen übersehen, wird die Mission scheitern und hunderte Leute werden von der Energieverpuffung pulverisiert werden.\n\nHoffentlich hat Thalyssra recht, was diesen Baum angeht.", sourceObjective = "Versiegelt die Arkusschnittstellen der Lunastrepassage, des Paradeplatzes und des Mitternachtshofs.", completion = "Wenn meine Karte vom Arkus stimmt, waren das jetzt alle Schnittstellen, um die wir uns kümmern mussten.", sourceObjectiveStatus = "unverified-source-field" }
quests[43565] = { id = 43565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebt Signale", description = "Die Leitung, die wir benötigen, befindet sich im Arkus, und seit Eurem letzten Besuch wurden dort die Wachen verdoppelt.\n\nUns bleibt nur eine Wahl. Wir müssen Euren Stoßtrupp direkt hineinteleportieren.\n\nDies wird ein Langstreckentransport zu einem unverankerten Ziel, also ein hartes Stück Arbeit.\n\nNehmt diesen Signalgeber und schaut Euch das Zentrum Suramars genauer an. Bringt mir anschließend den Signalgeber zur Auswertung wieder her.\n\nAuf diese Weise kann ich Euch so nah wie möglich zu der Leitung teleportieren!", sourceObjective = "Verwendet den verbesserten telemantischen Signalgeber, um das Immermondviertel, den Immermondbasar und die Sirenenwacht in Suramar zu untersuchen.", completion = "Ausgezeichnet. Damit ist das Risiko, dass ich Euch auf den Grund des Meeres teleportiere, sehr viel geringer!", sourceObjectiveStatus = "unverified-source-field" }
quests[43566] = { id = 43566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdorrte Fortschritte" }
quests[43567] = { id = 43567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles oder nichts", sourceObjective = "Schließt das Szenario \"Alles oder nichts\" ab.\n\nDas Szenario kann bei Großtelemant Oculeth gestartet werden.", completion = "Seht, die Erlösung der Nachtsüchtigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43568] = { id = 43568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcan'dor, Geschenk der uralten Magier", description = "Vor tausenden Jahren, als die Quel'dorei begannen, die Geheimnisse des Arkanen zu entdecken, traf sich eine kleine Gruppe Druiden mit dem obersten Elfenmagier.\n\nIm fahlen Mondlicht gründeten sie einen Orden, der danach streben sollte, das Arkane in ein Gleichgewicht zu bringen... und die Natur als Gefäß dafür zu benutzen. Deshalb wurden die Arcan'dor erschaffen.\n\nMeine Meister, die diesem Orden angehörten, sind schon längst gestorben. Doch ihr Vermächtnis bleibt.\n\nIhre Gabe wird den Geist der Shal'dorei wieder heilen. Lasst sie essen und heilen.", sourceObjective = "Pflückt die Frucht des Arcan'dor und teilt sie mit Großtelemant Oculeth, Arkanistin Valtrois und der Ersten Arkanistin Thalyssra.", progress = "Die Shal'dorei müssen die Frucht des Arcan'dor essen. Das ist die einzige Möglichkeit, sie zu befreien.", completion = "Endlich... Wir sind frei.", sourceObjectiveStatus = "unverified-source-field" }
quests[43569] = { id = 43569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arluins Anfrage", description = "Ich hätte nie gedacht, dass ich dies einmal lesen müsste...\n\n<Vanthir wiegt eine Schriftrolle in seiner Hand.>\n\nArluin hat... Pläne vorbereitet für den Fall, dass er fällt. Es ist nicht viel, aber ich würde gern seinen letzten Wunsch ehren.\n\n<Vanthir gibt Euch die Schriftrolle.>\n\nBegebt Euch zu dem auf der Karte markierten Ort. Nehmt diese Frucht vom Arcan'dor und gebt sie einer Frau namens Arluelle. Arluin hat sehr bestimmt festgelegt, dass jegliche Belohnung für seine Arbeit an sie gehen soll.\n\nIch denke, ihm könnte bewusst gewesen sein, was sein Opfer bedeutet. Ich habe mich in ihm getäuscht.", sourceObjective = "Sucht nach Arluelle und gebt Ihr einen Teil der Frucht des Arcan'dor.", progress = "Wo ist Arluin?", completion = "Ich bin nicht mehr hungrig. Ich kann denken... Ich werde leben! Oh, Arluin...", sourceObjectiveStatus = "unverified-source-field" }
quests[43571] = { id = 43571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharions Hort: Zopf des Unterkönigs", description = "Seid gegrüßt, <Todesgebieter/Todesgebieterin>. Seit unserer letzten Begegnung sind Jahre vergangen, aber für mich waren es nur wenige Tage.\n\nDas unheilige Band zwischen Reiter und Ross darf niemals unterschätzt werden. Macht führt zu mehr Macht, <Todesgebieter/Todesgebieterin>. Vergesst das nie!\n\nIch kann unzerstörbare Bande zwischen Reiter und Ross schmieden, aber dafür brauche ich einige mächtige Komponenten.\n\nAls Erstes brauche ich den Zopf des Unterkönigs, einen finsteren schamanischen Schmuck, der von Generation zu Generation vererbt wird.\n\nMomentan befindet er sich im Besitz von Dargrul dem Unterkönig.", sourceObjective = "Holt den Zopf des Unterkönigs aus Neltharions Hort.", progress = "Habt Ihr den Zopf des Unterkönigs?", completion = "Gut gemacht, Todesgebieter. Aus den Strängen des Zopfes fertigen wir die Zügel unserer Rösser.\n\nIch schätze, Dargrul wollte das gute Stück nur zu gern loswerden, nicht wahr?\n\n<Ein teuflisches Grinsen huscht über Salanars Gesicht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[43572] = { id = 43572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Die Alptraumpeitsche", description = "Die dunklen Rösser der Apokalypse sind unbeugsame Kreaturen der Qual und Grausamkeit. Man kann sie niemals zähmen... nur unterjochen.\n\nAls Nächstes brauchen wir eine Komponente der Macht, geboren aus Hass, hergestellt im Smaragdgrünen Alptraum. Man nennt sie die Alptraumpeitsche.\n\nDie Alptraumpeitsche vermag jegliche Hoffnung... alles Licht... einer Seele im Keim zu ersticken.\n\nGeführt wird die Peitsche vom Schemen von Xavius. Besiegt ihn und bringt mir die Peitsche!\n\nDamit werde ich die Rösser der Verdammten meinem Willen unterwerfen!", sourceObjective = "Holt die Alptraumpeitsche aus dem Finsterherzdickicht.", progress = "Habt Ihr die Alptraumpeitsche?", completion = "Endlich, die Alptraumpeitsche! Wenn ich sie in den Händen halte, spüre ich, dass die Legenden wahr sind.\n\nDiese Macht... diese Dunkelheit... diese... Qualen!\n\nJa, genau das brauchen wir.", sourceObjectiveStatus = "unverified-source-field" }
quests[43573] = { id = 43573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kriegsanstrengungen vorantreiben", description = "Die Suche nach den Vier Reitern hat zwar oberste Priorität, aber dennoch dürfen wir die Kriegsfront nicht vernachlässigen.\n\nAll unsere Erfolge auf dem Schlachtfeld haben die Brennende Legion schwer erschüttert. Daher greifen sie nun viel öfter und noch härter an.\n\nWir müssen diesem Ansturm weiterhin trotzen!\n\nErst, wenn wir diese Bedrohung im Griff haben, können wir den Vier Reitern unsere volle Aufmerksamkeit widmen.", sourceObjective = "Schließt 10 Weltquests ab.", completion = "Die Erfolge der Schwarzen Klinge auf dem Schlachtfeld sind der Brennenden Legion nicht verborgen geblieben.\n\nWährend wir unsere Kriegsanstrengungen vorantreiben, müssen wir auch die Streitkräfte von Sargeras im Auge behalten...", sourceObjectiveStatus = "unverified-source-field" }
quests[43574] = { id = 43574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund: Der Schlägel der Toten", description = "Wir haben jetzt alle notwendigen Gegenstände. Bald werden die unheiligen Rösser der Verdammten die Armeen der Brennenden Legion in den Staub trampeln.\n\nAber unsere Arbeit hier ist noch nicht getan. Ein Gegenstand entzieht sich uns nach wie vor...\n\nIn den Tiefen von Helheim regiert die gefallene Königin Helya über die Toten. Sie besitzt einen Schlägel, erfüllt von den Seelen zahlloser gefallener Krieger.\n\nBringt mir den Schlägel der Toten. Damit werde ich ein Geschirr schmieden, das so stark ist, dass es kein Dämon je zerschlagen kann!", sourceObjective = "Holt den Schlägel der Toten aus Helheim.", progress = "Habt Ihr den Schlägel der Toten?", completion = "Der legendäre Schlägel der Toten... Ich spüre die Wogen des Hasses und der Verzweiflung all der gequälten Seelen. Als Werkzeug des Elends ist dies wahrhaftige Perfektion.", sourceObjectiveStatus = "unverified-source-field" }
quests[43576] = { id = 43576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuformierung an der Zuflucht", description = "Ich kann hier nicht klar denken.\n\nDer Mondbrunnen ist zwar immer noch rein, aber der verderbliche Einfluss des Alptraums ist weiter vorhanden.\n\nKommt, lasst uns in die Zuflucht zurückkehren und unsere Gedanken sammeln. Danach werden wir weiter nach meinem Mann suchen.", sourceObjective = "Kehrt in die Sternensangzuflucht zurück.", completion = "Mein Verstand scheint schon viel klarer zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[43577] = { id = 43577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberung des Tors", description = "Die Zeit für den Vorstoß gegen die Legion ist gekommen.\n\nDie Legion unterhält mehrere Portale, verstreut über die Verheerten Inseln.\n\nSollten Eure Armeen eines der Tore sichern, solange es noch aktiv ist, kann Hymdall mit den Runensteinen, die Ihr gesammelt habt, das Tor auf die höllische Welt ausrichten, auf der die Legion Hodir gefangen hält.", sourceObjective = "Schließt folgende Missionen ab: \"Untersuchung der Teufelsseelenbastion\", \"Vorbereitung unserer Ankunft\", \"Eroberung des Tors\".", completion = "Die Valarjar haben das Tor der Legion am Teufelsfeuervorstoß eingenommen.\n\nJetzt wird es Zeit, dem Feind einen entscheidenden Schlag zu versetzen. Wir werden nicht abwarten, bis er hier angreift!", sourceObjectiveStatus = "unverified-source-field" }
quests[43578] = { id = 43578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looted Paladin Daily Mount" }
quests[43579] = { id = 43579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looted DK Daily Mount" }
quests[43580] = { id = 43580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Apothecary Faldren" }
quests[43581] = { id = 43581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Weisheit der Geduld", description = "Die Schrecken, denen Ihr im Dickicht die Stirn geboten habt, sind nur der Anfang. Im Smaragdgrünen Alptraum werdet Ihr Euch dem Kern der Verderbnis gegenübersehen, der die Stabilität jedes Lebens in Azeroth bedroht.\n\nAber noch nicht.\n\nEs ist uns noch nicht gelungen, die Magie zu durchdringen, die Xavius' finsteres Reich schützt. Sobald uns das allerdings gelingt, solltet Ihr hierher zurückkehren. Es gibt noch viel zu tun.", sourceObjective = "Wartet darauf, dass sich der Smaragdgrüne Alptraum öffnet, und erstattet dann Senegos in Azsuna Bericht.", completion = "Eure nächsten Schritte werden schwierig werden und noch gefährlicher als jede Bedrohung, der Ihr Euch bisher gegenübergesehen habt, doch Ihr müsst sie machen.\n\nZum Wohle von Azeroth.", sourceObjectiveStatus = "unverified-source-field" }
quests[43582] = { id = 43582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shalassic Park", description = "Wir haben einen Teufelssaurier.\n\nIch glaube, sie sieht Euch jetzt als Rudelführer an und sollte Euren Befehlen gehorchen.\n\nSie sieht hungrig aus. Wieso lasst Ihr sie nicht kurz von der Leine?", sourceObjective = "Reitet auf Su'esh und besiegt 50 Gegner.", completion = "Das war wirklich ein Spektakel, {name}.\n\nSu'esh wird in den kommenden Tagen sicher eine wertvolle Verbündete sein. Ich werde sie vorläufig im Auge behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[43583] = { id = 43583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Leben findet einen Weg" }
quests[43584] = { id = 43584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtenfürst der Valarjar" }
quests[43585] = { id = 43585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vorbereitung auf den Krieg", description = "Wir wären gut beraten, wenn wir unsere eigenen Streitkräfte verstärken, bevor wir Verbündete herbeirufen, die uns in der Entscheidungsschlacht gegen die Legion helfen sollen.\n\nEs gibt noch viel zu tun auf den Verheerten Inseln, und die Siege dort werden uns den nötigen Schwung geben, um den Feind zu zermalmen.", sourceObjective = "Schließt die Missionen \"Hilfe für die Valkyra\", \"Im Meer versunken\" und \"Von den Meeresriesen versklavt\" ab.", completion = "Ihr und Eure Armeen habt viel erreicht. Odyn hat seinen Kommandanten gut ausgesucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[43586] = { id = 43586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund: Nachricht für Helya", description = "Wir können nicht an zwei Fronten gleichzeitig kämpfen und siegen.\n\nWenn wir überhaupt eine Chance gegen die Legion haben wollen, müssen wir zunächst einen entscheidenden Sieg gegen Helya erringen. Nicht gegen ihre Armeen oder ihre Leutnants, sondern gegen die Mutter der Unterwelt höchstpersönlich.\n\nBegebt Euch zum Seelenschlund und besiegt Helya, {name}.", sourceObjective = "Bezwingt Helya im Dungeon \"Der Seelenschlund\".", completion = "Ein glorreicher Sieg! Es ist bedauerlich, dass Helya überlebt hat, aber nachdem Ihr nun die Armeen der Himmelsfeste anführt, wird sie es sich zweimal überlegen, bevor sie uns erneut angreift.", sourceObjectiveStatus = "unverified-source-field" }
quests[43587] = { id = 43587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leylinienzuleitung: Elor'shan", description = "<Die Leylinienzuleitung scheint intakt und unbeschädigt zu sein, aber dennoch funktioniert sie nicht. Eine Infusion mit uraltem Mana sollte sie eigentlich wieder zum Laufen bringen.>", sourceObjective = "Versorgt die Leylinienzuleitung mit uraltem Mana.", progress = "<Die Leylinienzuleitung pulsiert schwach.>", completion = "<Als Ihr das Mana in die Zuleitung gebt, erwacht die Struktur zum Leben. Ihr spürt auf der Haut, wie die umgebende Luft mit arkaner Macht aufgeladen wird.>", sourceObjectiveStatus = "unverified-source-field" }
quests[43588] = { id = 43588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leylinienzuleitung: Kel'balor", description = "<Diese Zuleitung scheint Energie von der Leylinie zu benötigen, um voll funktionstüchtig zu werden.\n\nIhr müsstet sie mit Mana versehen können, aber es wird ein paar Minuten dauern, genug Leylinienenergie zu beziehen, um die Infusion umzusetzen.\n\nPasst auf, denn von dem Schwall arkaner Energie könnten Kreaturen angezogen werden...>", sourceObjective = "Verteidigt die Leylinienzuleitung und verseht sie mit einer Infusion uralten Manas.", progress = "<Die Leylinienzuleitung pulsiert schwach.>", completion = "<Als Ihr das Mana in die Zuleitung gebt, erwacht die Struktur zum Leben. Ihr spürt auf der Haut, wie die umgebende Luft mit arkaner Macht aufgeladen wird.>", sourceObjectiveStatus = "unverified-source-field" }
quests[43589] = { id = 43589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leyline 03" }
quests[43590] = { id = 43590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leylinienzuleitung: Leystation Mondfall", description = "<Diese Leylinienzuleitung scheint beschädigt zu sein. Der große Sammler am oberen Ende ist unvollständig.\n\nDas fehlende, abgebrochene Stück muss hier irgendwo sein. Auf dem Boden seht Ihr einige Schleifspuren, die wohl von etwas Größerem stammen als den Kreaturen hier drinnen.\n\nEtwas viel Größerem.>", sourceObjective = "Sucht die abgebrochene Leydarschüssel und repariert die Leylinienzuleitung.", progress = "<Die Zuleitung pulsiert schwach.>", completion = "<Als Ihr das abgebrochene Stück auf der Säule platziert und es mit Mana versorgt, schließt sich der Bruch dank der arkanen Energie. Mit Aktivierung der Leylinie setzt langsam eine Drehung ein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[43591] = { id = 43591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leylinienzuleitung: Leystation Aethenar", description = "<Diese Leylinie scheint beschädigt zu sein und muss repariert werden.\n\nEinige große Stücke fehlen in der Hauptsäule, und in den Lücken knistert es vor arkaner Energie.\n\nDie Elementare in der Nähe heben anscheinend den Schutt auf und absorbieren ihn in ihre Körper. Vielleicht haben sie die fehlenden Stücke...>", sourceObjective = "Sammelt 6 Leylinienzuleitungsbruchstücke und versorgt die Zuleitung mit uraltem Mana.", progress = "<Die gesamte Leylinienzuleitung knistert, als die Energie unkontrolliert aus den Lücken in der Säule entweicht.>", completion = "<Als Ihr die Fragmente wieder in die Säule einsetzt, schließen sich langsam alle Risse dank der arkanen Energie. Ihr versorgt die Zuleitung mit uraltem Mana, und das gesamte Konstrukt erwacht zum Leben.>", sourceObjectiveStatus = "unverified-source-field" }
quests[43592] = { id = 43592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leylinienzuleitung: Der Arkus von Falanaar", description = "<Die Leylinienzuleitung scheint intakt und unbeschädigt zu sein, aber dennoch funktioniert sie nicht. Eine Infusion mit uraltem Mana sollte sie eigentlich wieder zum Laufen bringen.>", sourceObjective = "Versorgt die Leylinienzuleitung mit uraltem Mana.", progress = "<Die Leylinienzuleitung pulsiert schwach.>", completion = "<Als Ihr das Mana in die Zuleitung gebt, erwacht die Struktur zum Leben. Ihr spürt auf der Haut, wie die umgebende Luft mit arkaner Macht aufgeladen wird.>", sourceObjectiveStatus = "unverified-source-field" }
quests[43593] = { id = 43593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leylinienzuleitung: Die Falanaartiefen", description = "<Die Leylinienzuleitung scheint intakt und unbeschädigt zu sein, aber dennoch funktioniert sie nicht. Eine Infusion mit uraltem Mana sollte sie eigentlich wieder zum Laufen bringen.>", sourceObjective = "Versorgt die Leylinienzuleitung mit uraltem Mana.", progress = "<Die Leylinienzuleitung pulsiert schwach.>", completion = "<Als Ihr das Mana in die Zuleitung gebt, erwacht die Struktur zum Leben. Ihr spürt auf der Haut, wie die umgebende Luft mit arkaner Macht aufgeladen wird.>", sourceObjectiveStatus = "unverified-source-field" }
quests[43594] = { id = 43594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leylinienzuleitung: Die Hallen der Dunkelung", description = "<Die Leylinienzuleitung scheint intakt und unbeschädigt zu sein, aber dennoch funktioniert sie nicht. Eine Infusion mit uraltem Mana sollte sie eigentlich wieder zum Laufen bringen.>", sourceObjective = "Versorgt die Leylinienzuleitung mit uraltem Mana.", progress = "<Die Leylinienzuleitung pulsiert schwach.>", completion = "<Als Ihr das Mana in die Zuleitung gebt, erwacht die Struktur zum Leben. Ihr spürt auf der Haut, wie die umgebende Luft mit arkaner Macht aufgeladen wird.>", sourceObjectiveStatus = "unverified-source-field" }
quests[43595] = { id = 43595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrung der Gefallenen", description = "Seelen sind nicht das Einzige, wonach Helya trachtet, und die Kvaldir sind jederzeit bereit, ihr zu dienen.\n\nUnter ihrem Raubgut befinden sich auch die ehrwürdigen Klingen der gefallenen Helden, die den Kampf gegen Helyas Schergen wagten. Die Klingen gehören an einen ehrenwerten Ort, nicht in die Hände der Feinde.\n\nHolt diese Klingen zurück. Für die Ehre der Wellenskorn!", sourceObjective = "Sammelt 8 uralte Klingen der Wellenskorn von den Kvaldir im Höllenschlundmorast.", progress = "Habt Ihr die Klingen?", completion = "Ich werde dafür sorgen, dass die Klingen dahin zurückgebracht werden, wo sie hingehören.\n\nDie Toten danken es Euch, Fremder.", sourceObjectiveStatus = "unverified-source-field" }
quests[43596] = { id = 43596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund: Im Nebel stochern", description = "Vor Urzeiten war die Naglfar das Juwel von Helyas Flotte. Wie es scheint, hat das Schiff die Zeitalter überdauert und kann ihr nun erneut dienen.\n\nJetzt segelt das schreckliche Schiff auf dem Meer der Seelen und durchschneidet ungesehen von den Lebenden den Nebel. Die Kvaldir müssen eine Möglichkeit kennen, sie herbeizurufen, und die müsst Ihr herausfinden.\n\nFindet ihren Ankerplatz und geht an Bord der Naglfar. Bereitet dem Schiff ein Ende, dann können die Seelen der Wellenskorn vielleicht erlöst werden.", sourceObjective = "Besiegt Helya im Dungeon 'Der Seelenschlund' und kehrt danach zu Havi in Valdisdall zurück.", completion = "Wenn das Schreckensschiff zerrissen ist, werden die Seelen der Toten ihr Urteil erhalten.\n\nOdyn wird seine Champions haben und die Wellenskorn ihre Ehre.", sourceObjectiveStatus = "unverified-source-field" }
