quests[43604] = { id = 43604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund: Ymirons zerbrochene Klinge", description = "Ihr tragt die Klinge von König Ymiron und Euch ist klar, wie mächtig er als Verbündeter wäre.\n\nVielleicht ließe sich Odyn überzeugen, den Geist des Vrykulkönigs dazu zu zwingen, in Eurer Armee zu kämpfen.", sourceObjective = "Kehrt zur Himmelsfeste zurück und überzeugt Odyn, König Ymiron zu erwecken.", completion = "Also gut. So sei es!", sourceObjectiveStatus = "unverified-source-field" }
quests[43605] = { id = 43605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Arkanist Shal'iman" }
